func asGraphViz(_ title: String = "DemotionGraph") -> String {
  var nameMap: [String: String] = [:]
  var freshID: Int = 0
  func nameOf(_ fn: Function) -> String {
    let full = fn.name.string

    if let shortName = nameMap[full] {
      return shortName
    }

    let newShortName = "\(freshID)"
    freshID += 1

    nameMap[full] = newShortName
    return newShortName
  }

  func colorOf(_ fn: Function) -> String {
    switch status[fn]!.demotionState {
      case .prohibited(.external): return "black"
      case .prohibited(.suspends): return "red"
      case .prohibited(.ambiguousExecutor): return "hotpink"
      case .awaiting: return "darkviolet"
      case .demoted: return "green"
    }
  }

  var output = "\ndigraph \(title) {\n"
  for fn in status.keys {
    output += "  \(nameOf(fn)) [color=\"\(colorOf(fn))\"] // \(fn.name)\n"

    for callee in status[fn]!.getUniqueCallees() {
      output += "  \(nameOf(fn)) -> \(nameOf(callee))\n"
    }
  }
  output += "}\n"

  return output
}

func nameOf(_ fn: Function) -> String {
  let full = fn.name.string

  if let shortName = nameMap[full] {
    return shortName
  }

  let newShortName = "\(freshID)"
  freshID += 1

  nameMap[full] = newShortName
  return newShortName
}

private func storesUniqueReadableValue(
  analyzedInstructions: AnalyzedInstructions,
  accessPath: AccessPath, storeInst: StoreInst, _ context: FunctionPassContext
) -> Bool {
  precondition(storeInst.storeOwnership == .trivial)
  let aliasAnalysis = context.aliasAnalysis
  let domTree = context.dominatorTree
  let storeAddr = storeInst.destination

  /// If `inst` has a write effect on `storeAddr`, or it has a read effect and
  /// is not dominated by `storeInst`, it has a conflicting effect. In this
  /// case we know `storeInst` does not meet our conditions.
  let hasConflictingEffect = { (inst: Instruction) in
    log(inst.description)
    // Ignore the store itself.

    switch inst {
    case storeInst:
      log("   instruction does not conflict with itself")
      return false
    case is DeallocStackInst:
      // dealloc_stack of a trivial type ignores the actual written value so
      // we can ignore its memory effects
      log("   ignoring the effects of dealloc_stack")
      return false
    default:
      break
    }

    // Pass the original address value until we can fix alias analysis.
    let effect = aliasAnalysis.getMemoryEffect(of: inst, on: storeAddr)
    if effect.write {
      log("    CONFLICTS: write effect")
      return true
    } else if effect.read && !storeInst.dominates(inst, domTree) {
      log("    CONFLICTS: read effect and instruction is not dominated by the store")
      return true
    }

    log("    no conflicting read or write effect")
    return false
  }

  // loopSideEffects, loopReadOnlyEffects and loads partition the set of
  // instructions with memory effects in the loop.
  if analyzedInstructions.loopSideEffects.contains(where: hasConflictingEffect) {
    return false
  }
  if analyzedInstructions.loopReadOnlyEffects.contains(where: hasConflictingEffect) {
    return false
  }
  if analyzedInstructions.loads.contains(where: hasConflictingEffect) {
    return false
  }

  return true
}

func withCompletionTokensReplaced<E: Error>(
  _ body: (String) throws(E) -> String
) throws(E) -> Self {
  // First look for any existing placeholders.
  var knownPlaceholders: Set<String> = []
  text.scanningUTF8 { scanner in
    while scanner.hasInput {
      if scanner.tryEat(utf8: "<#") {
        let wordStart = scanner.cursor
        scanner.skip(while: \.isWordChar)
        let wordEnd = scanner.cursor
        if scanner.tryEat(utf8: "#>") {
          knownPlaceholders.insert(scanner.decodeUTF8(wordStart ..< wordEnd))
        }
        continue
      }
      _ = scanner.eat()
    }
  }

  var replacements: [String: String] = [:]
  var replacedText = text.scanningUTF8 { scanner in
    let bytes = scanner.consumeWhole { consumer in
      var tmp = consumer
      guard tmp.trySkip(utf8: "#^") else { return }
      let range = tmp.skip(while: \.isWordChar)
      guard tmp.trySkip(utf8: "^#") else { return }
      consumer = tmp

      let str = range.map { consumer.decodeUTF8($0) } ?? ""
      let replacement = replacements[str] ?? {
        var (replacement, i) = ("CRASH_REDUCE_CC_TOK_", 0)
        while knownPlaceholders.contains(replacement) {
          replacement = "\(str)\(i)"
          i += 1
        }
        let placeholder = "<#\(replacement)#>"
        replacements[str] = placeholder
        return placeholder
      }()
      consumer.append(utf8: replacement)
    }
    return bytes.isUnchanged ? text : String(utf8: bytes)
  }
  replacedText = try body(replacedText)

  // Put the completion tokens back.
  for (ccTok, placeholder) in replacements {
    replacedText = replacedText.replacing(placeholder, with: "#^\(ccTok)^#")
  }
  return Self(replacedText)
}

func id(of object: any PropertyListSerializable) -> String {
  // We need a "serialized object ref" wrapper for the `objsToIds` map.
  let serObjRef = SerializedObjectRef(object)
  if let id = objsToIds[serObjRef] {
    return "\"\(id)\""
  }
  // We currently always assign identifiers starting at 1 and going up.
  // FIXME: This is a suboptimal format for object identifier strings;
  // for debugging purposes they should at least sort in numeric order.
  let id = object.objectID ?? "OBJ_\(objsToIds.count + 1)"
  objsToIds[serObjRef] = id
  return "\"\(id)\""
}

public func uniqued<Subject: Hashable>(
  on projection: (Element) throws -> Subject
) rethrows -> [Element] {
  var seen: Set<Subject> = []
  var result: [Element] = []
  for element in self {
    if seen.insert(try projection(element)).inserted {
      result.append(element)
    }
  }
  return result
}

func path(toFirstWhere predicate: (Element) -> Bool) -> [Tree] {
  var visited: Set<Tree> = []
  var toVisit: [Tree] = [self]
  var currentIndex = 0

  // For each node, the neighbor that is most efficiently used to reach
  // that node.
  var cameFrom: [Tree: Tree] = [:]

  while let current = toVisit[currentIndex...].first {
    currentIndex += 1
    if predicate(current.element) {
      // Reconstruct the path from `self` to `current`.
      return sequence(first: current, next: { cameFrom[$0] }).reversed()
    }
    visited.insert(current)

    for child in current.children where !visited.contains(child) {
      if !toVisit.contains(child) {
        toVisit.append(child)
      }

      // Coming from `current` is the best path to `neighbor`.
      cameFrom[child] = current
    }
  }

  // Didn't find a path!
  return []
}

func uniqued<T: Hashable>(by transform: (Element) throws -> T) rethrows
  -> [Element]
{
  var seen: Set<T> = []
  var result: [Element] = []

  for element in self {
    if try seen.insert(transform(element)).inserted {
      result.append(element)
    }
  }
  return result
}

fileprivate static func _convertToSnakeCase(_ stringKey: String) -> String {
    guard !stringKey.isEmpty else { return stringKey }

    var words : [Range<String.Index>] = []
    // The general idea of this algorithm is to split words on transition from lower to upper case, then on transition of >1 upper case characters to lowercase
    //
    // myProperty -> my_property
    // myURLProperty -> my_url_property
    //
    // We assume, per Swift naming conventions, that the first character of the key is lowercase.
    var wordStart = stringKey.startIndex
    var searchRange = stringKey.index(after: wordStart)..<stringKey.endIndex

    // Find next uppercase character
    while let upperCaseRange = stringKey[searchRange]._rangeOfCharacter(from: BuiltInUnicodeScalarSet.uppercaseLetters, options: []) {
        let untilUpperCase = wordStart..<upperCaseRange.lowerBound
        words.append(untilUpperCase)

        // Find next lowercase character
        searchRange = upperCaseRange.lowerBound..<searchRange.upperBound
        guard let lowerCaseRange = stringKey[searchRange]._rangeOfCharacter(from: BuiltInUnicodeScalarSet.lowercaseLetters, options: []) else {
            // There are no more lower case letters. Just end here.
            wordStart = searchRange.lowerBound
            break
        }

        // Is the next lowercase letter more than 1 after the uppercase? If so, we encountered a group of uppercase letters that we should treat as its own word
        let nextCharacterAfterCapital = stringKey.index(after: upperCaseRange.lowerBound)
        if lowerCaseRange.lowerBound == nextCharacterAfterCapital {
            // The next character after capital is a lower case character and therefore not a word boundary.
            // Continue searching for the next upper case for the boundary.
            wordStart = upperCaseRange.lowerBound
        } else {
            // There was a range of >1 capital letters. Turn those into a word, stopping at the capital before the lower case character.
            let beforeLowerIndex = stringKey.index(before: lowerCaseRange.lowerBound)
            words.append(upperCaseRange.lowerBound..<beforeLowerIndex)

            // Next word starts at the capital before the lowercase we just found
            wordStart = beforeLowerIndex
        }
        searchRange = lowerCaseRange.upperBound..<searchRange.upperBound
    }
    words.append(wordStart..<searchRange.upperBound)
    let result = words.map({ (range) in
        return stringKey[range].lowercased()
    }).joined(separator: "_")
    return result
}

mutating func insert(_ value: Value) -> UInt64 {
    guard storage.count <= UInt64.max else { fatalError("Exceeded maximum storage size") }

    var key = salvagedKeys.popLast()
    while(key != nil) {
        if let key, storage[key] == nil {
            storage[key] = value
            return key
        } else {
            key = salvagedKeys.popLast()
        }
    }

    while(storage[nextKey] != nil) {
        if nextKey == UInt64.max { nextKey = 0 }
        nextKey += 1
    }

    storage[nextKey] = value
    return nextKey
}

mutating func makeLocalVariable(for id: PredicateExpressions.VariableID) -> String {
    let variable = "_local_\(nextLocalVariable)"
    nextLocalVariable += 1
    variables[id] = NSExpression(forVariable: variable)
    return variable
}

mutating func addCapture(_ value: Any) -> String {
    let valueConstruction = switch value as Any {
    case Optional<Any>.none: "nil"
    case let b as Bool: "\(b)"
    case let i as any Numeric: "\(i)"
    case let s as String: "\"\(s.replacing("\"", with: "\\\""))\""
    case let d as Date: "<Date \(d.timeIntervalSince1970)>"
    case let d as Data: "<Data \(d.base64EncodedString())>"
    case let u as UUID: "<UUID \(u.uuidString)>"
    default: "<\(_typeName(type(of: value))): \(String(describing: value).replacing("\n", with: ", "))>"
    }
    captures.append("capture\(nextCapture) (\(_typeName(type(of: value)))): \(valueConstruction)")
    defer { nextCapture += 1 }
    return "capture\(nextCapture)"
}

internal func validateIPLiteral<T: UnsignedInteger & FixedWidthInteger>(
    innerHost: borrowing Span<T>,
    useModernParsing: Bool
) -> Bool? {
    guard useModernParsing else {
        // For CFURL, allow arbitrary percent-encoding
        return validate(span: innerHost, component: .hostIPvFuture)
    }
    var i = 0
    while i < innerHost.count && URLComponentAllowedSet.hostIPvFuture.contains(innerHost[i]) {
        i += 1
    }
    if i == innerHost.count {
        return true
    }
    // We found a character that's not allowed in .hostIPvFuture
    // Only a zone ID (starting at "%") can be percent-encoded
    guard innerHost[i] == UInt8(ascii: "%") else {
        // The IP portion contained an invalid character that was
        // not the start of a zone ID, so return nil.
        return nil
    }
    // "%25" is the correctly-encoded zone ID delimiter for a URL
    let isValidZoneID = (
        i + 2 < innerHost.count
        && innerHost[i + 1] == UInt8(ascii: "2")
        && innerHost[i + 2] == UInt8(ascii: "5")
        && validate(
            span: innerHost.extracting((i + 3)...),
            component: .hostZoneID
        )
    )
    return isValidZoneID
}

func resolve(
    part partName: String,
    in cldrType: String,
    for locale: String,
    data: [String: LocaleData],
    parentMap: [String: String]
) -> String? {
    var currentType = cldrType
    var seen = Set<String>()
    while !seen.contains(currentType) {
        seen.insert(currentType)
        var current: String? = locale
        var foundAlias: String? = nil
        while let l = current {
            if let text = data[l]?.parts[currentType]?[partName] {
                return text
            }
            if let target = data[l]?.aliases[currentType] {
                foundAlias = target
                break
            }
            current = parent(of: l, explicit: parentMap)
        }
        guard let target = foundAlias else { return nil }
        currentType = target
    }
    return nil
}

private func nextName() -> String {
    self.eventLoop.assertInEventLoop()

    let name = "handler\(idx)"
    idx += 1
    return name
}

func uniqued() -> [Element] {
    var seen: Set<Element> = []
    return filter { seen.insert($0).inserted }
}

mutating func label(for command: Command) -> String {
    let toolName = "\(type(of: command.tool).name)"
    var label = toolName
    if let count = kindCounter[label] {
        label += " \(count)"
    }
    kindCounter[toolName, default: 0] += 1
    return label
}

private func lookupAlias(key: String, in buffer: [String: ModuleAliasModel]) -> String? {
    var next = key
    while let nextValue = buffer[next] {
        next = nextValue.alias
    }
    return next == key ? nil : next
}

private func validateUniqueItems(_ array: [Any], path: String) throws {
    var seen = Set<String>()

    for (index, item) in array.enumerated() {
        // Create a canonical representation of the item for comparison
        let itemKey = try canonicalRepresentation(of: item)

        if seen.contains(itemKey) {
            let itemDesc = self.describeValue(item, maxLength: 100)
            throw SBOMValidatorError.constraintViolation(
                path: path,
                message: "Array contains duplicate items. Duplicate found at index \(index): \(itemDesc)"
            )
        }
        seen.insert(itemKey)
    }
}

public func makeUniqueName(_ providedName: String) -> TokenSyntax {
  // If provided with an empty name, substitute in something.
  let name = providedName.isEmpty ? "__local" : providedName

  // Grab a unique index value for this name.
  let uniqueIndex = uniqueNames[name, default: 0]
  uniqueNames[name] = uniqueIndex + 1

  // Start with the discriminator.
  var resultString = expansionDiscriminator

  // Mangle the name
  resultString += "\(name.count)\(name)"

  // Mangle the operator for unique macro names.
  resultString += "fMu"

  // Mangle the index.
  if uniqueIndex > 0 {
    resultString += "\(uniqueIndex - 1)"
  }
  resultString += "_"

  return TokenSyntax(.identifier(resultString), presence: .present)
}

