}

private static func extractJSONCandidates(from raw: String) -> [String] {
    var found: [String] = []
    var index = raw.startIndex
    while let openIndex = raw[index...].firstIndex(of: "{") {
        var depth = 0
        var cursor = openIndex
        while cursor < raw.endIndex {
            let char = raw[cursor]
            if char == "{" {
                depth += 1
            } else if char == "}" {
                depth -= 1
                if depth == 0 {
                    let next = raw.index(after: cursor)
                    found.append(String(raw[openIndex..<next]))
                    index = next
                    break
                }
            }
            cursor = raw.index(after: cursor)
        }
        if depth != 0 { break }
    }
    return found
}

private func uniqueRuleIDs(in violations: [SwiftLintViolation]) -> [String] {
    var seen = Set<String>()
    var ordered: [String] = []
    for violation in violations where seen.insert(violation.ruleID).inserted {
        ordered.append(violation.ruleID)
    }
    return ordered
}

static func isFreshConstruction(_ token: TokenSyntax) -> Bool {
    guard freshConstructions.contains(token.text),
          let reference = token.parent?.as(DeclReferenceExprSyntax.self) else { return false }
    var callee = Syntax(reference)
    if let member = reference.parent?.as(MemberAccessExprSyntax.self), member.base?.id == reference.id,
       member.declName.baseName.tokenKind == .keyword(.`init`) {
        callee = Syntax(member)
    }
    guard let call = callee.parent?.as(FunctionCallExprSyntax.self), call.calledExpression.id == callee.id else {
        return false
    }
    return call.arguments.isEmpty && call.trailingClosure == nil
}

static func renderSummary(results: [AcceptCheckResult]) -> String {
    if results.isEmpty {
        return "swift-infer accept-check: no accepted decisions to re-check.\n"
    }
    var lines: [String] = []
    let suffix = results.count == 1 ? "" : "s"
    lines.append(
        "swift-infer accept-check — re-verified \(results.count) accepted decision\(suffix):"
    )
    lines.append("")
    for result in results {
        let detail = result.detail.map { " (\($0))" } ?? ""
        lines.append(
            "  \(result.record.identityHash)  \(result.record.template)  "
                + "\(result.kind.rawValue)\(detail)"
        )
    }
    lines.append("")
    var counts: [PostAcceptanceOutcomeKind: Int] = [:]
    for result in results {
        counts[result.kind, default: 0] += 1
    }
    lines.append("Summary:")
    for kind in PostAcceptanceOutcomeKind.allCases {
        lines.append("  \(kind.rawValue): \(counts[kind] ?? 0)")
    }
    return lines.joined(separator: "\n") + "\n"
}

static func nClassEquivalenceClassFileContents(hint: NClassEquivalenceClassHint) -> String {
    var lines: [String] = []
    lines.append("// Auto-generated by `swift-infer discover --interactive` — do not edit.")
    lines.append("//")
    let header = "// Inferred N-class equivalence partition for "
        + "\(hint.predicateName)(_: \(hint.argTypeName)) -> \(hint.returnTypeName)"
        + " across \(hint.markerSetName)"
    lines.append(header)
    lines.append("//")
    for marker in hint.markers {
        let count = hint.siteCountsByMarker[marker] ?? 0
        let line = "//   • \(count) test methods named \(marker)*"
            + " assert \(hint.predicateName)(x) is .\(lowercaseFirst(marker))"
        lines.append(line)
    }
    lines.append("//")
    if let veto = hint.predicateVeto {
        lines.append("// Generator narrowing skipped: \(veto.advisoryReason).")
    } else {
        for marker in hint.markers {
            if let generator = hint.suggestedGeneratorsByMarker[marker] {
                lines.append("// Suggested generator for \(marker) class: \(generator)")
            }
        }
    }
    lines.append("//")
    if hint.coversDomain {
        let cases = hint.markers.map { ".\(lowercaseFirst($0))" }.joined(separator: " ∨ p(x) == ")
        lines.append("// Exhaustiveness: forAll x: \(hint.argTypeName)."
            + " p(x) == \(cases)"
            + " — markers cover every case of \(hint.returnTypeName).")
        lines.append("//")
    }
    let caveat = "// Caveat: \(hint.predicateName) may reject most random"
        + " \(hint.argTypeName)s for any single bucket; if so, prefer"
        + " constructing custom Gens per bucket instead of relying on filter."
    lines.append(caveat)
    return lines.joined(separator: "\n") + "\n"
}

private static func tierBreakdown(_ tiers: [String]) -> String {
    var counts: [String: Int] = [:]
    for tier in tiers { counts[tier, default: 0] += 1 }
    let parts = tierOrder.compactMap { tier -> String? in
        let count = counts[tier] ?? 0
        return count == 0 ? nil : "\(tier) \(count)"
    }
    return parts.isEmpty ? "(no tiers)" : parts.joined(separator: " · ")
}

static func rawDelimiterCount(for snippet: String) -> Int {
    var count = 1
    while snippet.contains("\"\"\"" + String(repeating: "#", count: count))
            || snippet.contains("\\" + String(repeating: "#", count: count)) {
        count += 1
    }
    return count
}

private static func uniqueCaseName(
    for action: ViewModelAction,
    taken: inout Set<String>
) -> String {
    var candidate = action.name
    if taken.contains(candidate) {
        let labelSuffix = action.parameters
            .map { $0.label.map(capitalizedFirst) ?? "Unlabeled" }
            .joined()
        if !labelSuffix.isEmpty { candidate = action.name + labelSuffix }
    }
    var unique = candidate
    var counter = 2
    while taken.contains(unique) {
        unique = "\(candidate)\(counter)"
        counter += 1
    }
    taken.insert(unique)
    return escapeIfKeyword(unique)
}

private static func tierBreakdown(
    _ suggestions: [Suggestion],
    verifyEvidenceByIdentity: [String: VerifyEvidence] = [:]
) -> String {
    var counts: [Tier: Int] = [:]
    for suggestion in suggestions {
        // The EFFECTIVE tier, exactly as `render` computes it. Until v1.149 this read
        // `suggestion.score.tier` and the map was never passed, so `renderStats` could not
        // say `Verified` at all: `.verified` is set by the surfacing pipeline rather than
        // derived from the score, and a 100-point row falls out as `Strong`. Measured on
        // this repo, `SwiftInferCore` printed "36 Strong" where the truth was 33 Verified
        // + 3 Strong, and `SwiftInferCLI` "22" where it was 18 + 4 — both adding up
        // exactly. That both inflates `Strong` and hides the tool's best result, in the
        // view a CI dashboard reads.
        let effectiveTier = suggestion.score.tier.promoted(
            byVerifyOutcome: verifyEvidenceByIdentity[suggestion.identity.normalized]?.outcome
        )
        counts[effectiveTier, default: 0] += 1
    }
    let parts: [String] = Tier.allCases.sorted().filter { $0 != .suppressed }.compactMap { tier in
        guard let value = counts[tier], value > 0 else { return nil }
        return "\(value) \(tier.label)"
    }
    return parts.joined(separator: ", ")
}

public static func expression(for typeName: String, classes: [String: ClassDecl]) -> (String, Bool)? {
    let bare = typeName.components(separatedBy: ".").last ?? typeName
    var current = bare
    var seen: Set<String> = []
    while seen.insert(current).inserted {
        guard let decl = classes[current] else {
            return current == "SyntaxVisitor" ? ("\(typeName)(viewMode: .sourceAccurate)", true) : nil
        }
        if !decl.initializers.isEmpty {
            guard let usable = decl.initializers.first(where: isTrivial) else { return nil }
            let arguments = usable.parameters.compactMap { parameter -> String? in
                guard let value = parameter.value, !value.isEmpty else { return nil }
                return parameter.label.map { "\($0): \(value)" } ?? value
            }
            return ("\(typeName)(\(arguments.joined(separator: ", ")))", false)
        }
        guard let superclass = decl.superclass else { return ("\(typeName)()", false) }
        current = superclass
    }
    return nil
}

static func shapeDisambiguationVeto(for summary: FunctionSummary) -> Signal? {
    // Common shape gate: single non-inout param, non-mutating,
    // non-Void return (the typeSymmetry shape gate from
    // typeSymmetrySignal). Re-checked here so the veto is robust
    // to call-site re-ordering.
    guard summary.parameters.count == 1,
          let param = summary.parameters.first,
          !param.isInout,
          !summary.isMutating,
          let returnType = summary.returnTypeText,
          returnType != "Void",
          returnType != "()" else {
        return nil
    }

    let name = summary.name

    // Pattern 1: capacity / scale domain conversion — `(Int) -> Int`
    // shape AND name contains a domain-conversion token AND first-
    // param label is a cross-domain marker. Both conditions required
    // to avoid false positives on curated idempotence verbs that
    // happen to use `forScale:` etc. (e.g., `normalize(forScale:)`).
    //
    // Catches both directions:
    //   - `_minimumCapacity(forScale:)` (capacity-FROM-scale)
    //   - `_scale(forCapacity:)` (scale-FROM-capacity; "Scale" / "scale" in name)
    //   - `wordCount(forScale:)` (Count token)
    // Skips: `normalize(forScale:)`, `simplify(forScale:)` (no
    // Capacity/Count/Scale token in name).
    if returnType == "Int", param.typeText == "Int" {
        let domainTokens = ["Capacity", "Count", "Scale", "scale"]
        let nameHit = domainTokens.contains { name.contains($0) }
        let labelHit: Bool = {
            guard let label = param.label else { return false }
            return label == "forScale" || label == "forCapacity"
        }()
        if nameHit, labelHit {
            let labelStr = param.label ?? "_"
            return Signal(
                kind: .protocolCoveredProperty,
                weight: Signal.vetoWeight,
                detail: "Shape-coincidence: '\(name)(\(labelStr):)' is a "
                    + "cross-domain Int conversion (capacity↔scale family) "
                    + "with `(Int) -> Int` shape; `\(name)(\(name)(s))` "
                    + "is a type-shape coincidence, not an idempotent "
                    + "fixed-point operation"
            )
        }
    }

    return formatterVeto(name: name, param: param, returnType: returnType)
}

private func nClassEquivalenceClassExplainability(hint: NClassEquivalenceClassHint) -> ExplainabilityBlock {
    let header = "Predicate \(hint.predicateName)(_: \(hint.argTypeName))"
        + " -> \(hint.returnTypeName) partitions \(hint.markerSetName)"
        + " across the test corpus:"
    var why = [header]
    for marker in hint.markers {
        let count = hint.siteCountsByMarker[marker] ?? 0
        why.append("  • \(count) sites named \(marker)*"
            + " assert \(hint.predicateName)(x) == .\(marker.lowercasedFirst())")
    }
    if let veto = hint.predicateVeto {
        why.append("Generator narrowing skipped: \(veto.advisoryReason).")
    } else {
        for marker in hint.markers {
            if let generator = hint.suggestedGeneratorsByMarker[marker] {
                why.append("Suggested generator for \(marker) class: \(generator)")
            }
        }
    }
    if hint.coversDomain {
        why.append("Exhaustiveness: forAll x: \(hint.argTypeName)."
            + " disjunction over \(hint.markers.count) buckets covers"
            + " every case of \(hint.returnTypeName).")
    }
    let advisoryCaveat = "Advisory only — the equivalence class is documentation,"
        + " not a runnable property. Author per-class properties manually using"
        + " the suggested filter generators."
    return ExplainabilityBlock(whySuggested: why, whyMightBeWrong: [advisoryCaveat])
}

private static func appendUnique(_ ruleId: String, to list: inout [String]?) {
    var current = list ?? []
    if !current.contains(ruleId) {
        current.append(ruleId)
        list = current
    }
}

func hasUniqueAttribute(_ attributes: AttributeListSyntax) -> Bool {
    attributes.contains { attr in
        guard let attrSyntax = attr.as(AttributeSyntax.self),
              attrSyntax.attributeName.trimmedDescription == "Attribute",
              let args = attrSyntax.arguments?.as(LabeledExprListSyntax.self) else {
            return false
        }
        return args.contains { arg in
            arg.expression.trimmedDescription.contains(".unique")
        }
    }
}

mutating func id(forKey key: String, sanitizing text: String) -> String {
    if let existing = byKey[key] {
        return existing
    }
    let base = sanitize(text)
    var candidate = base
    var suffix = 2
    while taken.contains(candidate) {
        candidate = "\(base)_\(suffix)"
        suffix += 1
    }
    byKey[key] = candidate
    taken.insert(candidate)
    return candidate
}

func uniqName(item: SyntaxStructure, relationship: String) -> String {
    guard let name = item.fullName else { return "" }
    var newName = name
    if uniqElementNames.contains(name) {
        // The counter is diagram-wide, so where no candidate is taken every alias is what
        // it always was; a taken candidate is skipped, never reused.
        repeat {
            newName = name + "\(index)"
            index += 1
        } while takenIdentifiers.contains(newName)
    } else {
        uniqElementNames.append(name)
        uniqElementAndTypes[name] = relationship
    }
    if item.kind == .extension {
        addExtensionEdge(from: item, alias: newName, relationship: relationship)
    }
    if declaresIdentifier(of: item) {
        takenIdentifiers.insert(newName)
    }
    uniqueNameForElement[item] = newName
    linkTypeForElement[item] = linkType(for: relationship)
    return newName
}

mutating func issue(for name: String) -> String {
    var nodeId = name
    if issuedNames.contains(name) {
        var counter = 1
        repeat {
            nodeId = "\(name)_\(counter)"
            counter += 1
        } while taken.contains(nodeId)
    }
    issuedNames.insert(name)
    taken.insert(nodeId)
    return nodeId
}

private static func uniqued(_ transitions: [StateTransition]) -> [StateTransition] {
    var seen: Set<StateTransition> = []
    return transitions.filter { seen.insert($0).inserted }
}

private static func appendStructureInsights(from summary: ProjectSummary, to insights: inout [Insight]) {
    if summary.totalTypes > 0 {
        let parts = summary.typeBreakdown
            .sorted { $0.value > $1.value }
            .map { "\($0.value) \($0.key.lowercased())" }
            .joined(separator: ", ")
        insights.append(Insight(
            icon: "chart.pie.fill",
            title: "Project composition",
            description: "Your project has \(parts).",
            severity: .info
        ))
    }

    let protocolCount = summary.typeBreakdown["Protocols"] ?? 0
    if protocolCount >= 3 {
        insights.append(Insight(
            icon: "checklist",
            title: "\(protocolCount) protocols found",
            description: "See how your types conform to shared interfaces.",
            severity: .info
        ))
    }

    if summary.totalRelationships == 0 && summary.totalTypes > 0 {
        insights.append(Insight(
            icon: "circle.dashed",
            title: "No type relationships found",
            description: "Your types appear to be independent — no inheritance or conformance detected.",
            severity: .info
        ))
    }
}

public func auditedTag(forCents cents: Int) -> String {
    auditCounter += 1
    return canonicalTag(forCents: cents) + " (seen \(auditCounter))"
}

func color(_ graph: SimpleGraph) -> [Int] {
    var colors = Array(repeating: -1, count: graph.vertexCount)
    for vertex in 0..<graph.vertexCount {
        let taken = Set(graph.adjacency[vertex].compactMap { colors[$0] == -1 ? nil : colors[$0] })
        var candidate = 0
        while taken.contains(candidate) { candidate += 1 }
        colors[vertex] = candidate
    }
    return colors
}

public func color(_ graph: SimpleGraph) -> [Int] {
    var colors = Array(repeating: -1, count: graph.vertexCount)
    for vertex in (0..<graph.vertexCount).reversed() {
        let taken = Set(graph.adjacency[vertex].compactMap { colors[$0] == -1 ? nil : colors[$0] })
        var candidate = 0
        while taken.contains(candidate) { candidate += 1 }
        colors[vertex] = candidate
    }
    return colors
}

func insertUniquely(server: OpenAPI.Server) {
    let serverHash = hash(for: server)
    if !seenHashes.contains(serverHash) {
        seenHashes.insert(serverHash)
        collectedServers.append(server)
    }
}

func uniqueParametersForCurrentPath(_ operation: DereferencedOperation) -> [DereferencedParameter] {
    let allParameters = operation.parameters + pathItem.parameters

    var seenParameterIdentities = Set<OpenAPI.Parameter.ParameterIdentity>()
    var uniqueParameters = [DereferencedParameter]()

    for parameter in allParameters {
        let identity = OpenAPI.Parameter.ParameterIdentity(name: parameter.name, location: parameter.location)
        if !seenParameterIdentities.contains(identity) {
            seenParameterIdentities.insert(identity)
            uniqueParameters.append(parameter)
        }
    }
    return uniqueParameters
}

func uniqueElements<Key: Hashable>(by keyForValue: (Element) -> Key) -> [Element] {
    var seen: Set<Key> = []
    var result: [Element] = []
    for element in self {
        let property = keyForValue(element)
        if !seen.contains(property) {
            result.append(element)
            seen.insert(property)
        }
    }
    return result
}

private func disambiguatedPaths(
    caseSensitive: Bool,
    transformToFileNames: Bool,
    includeDisambiguationForUnambiguousChildren: Bool,
    includeLanguage: Bool,
    allowAdvancedDisambiguation: Bool
) -> [String: String] {
    let nameTransform: (String) -> String = if transformToFileNames {
        symbolFileName(_:)
    } else {
        { $0 }
    }

    var pathsByUSR: [String: String] = [:]

    func descend(_ node: borrowing Node, accumulatedPath: consuming String, updating pathsByUSR: inout [String: String]) {
        let children = [String: DisambiguationContainer](node.children.map {
            var name = $0.key
            if !caseSensitive {
                name = name.lowercased()
            }
            return (nameTransform(name), $0.value)
        }, uniquingKeysWith: { $0.merge(with: $1) })

        for (_, container) in children {
            let disambiguatedChildren = container.disambiguatedValuesWithCollapsedUniqueSymbols(includeLanguage: includeLanguage, allowAdvancedDisambiguation: allowAdvancedDisambiguation)
            let uniqueNodesWithChildren = Set(disambiguatedChildren.filter { $0.disambiguation != .none && !$0.value.children.isEmpty }.map { $0.value.symbol?.identifier.precise })

            for (node, disambiguation) in disambiguatedChildren {
                var path = "\(accumulatedPath)/\(nameTransform(node.name))"
                if node.identifier == nil && disambiguatedChildren.count == 1 {
                    let element = container.storage.first!
                    // When descending through placeholder nodes, we trust that the known disambiguation
                    // that they were created with is necessary.
                    if let kind = element.kind {
                        path.append("-\(kind)")
                    }
                    if let hash = element.hash {
                        path.append("-\(hash)")
                    }
                }
                if let symbol = node.symbol,
                   // If a symbol node exist in multiple languages, prioritize the Swift variant.
                   node.counterpart == nil || symbol.identifier.interfaceLanguage == "swift"
                {
                    let newPath = path.appending(disambiguation.makeSuffix())
                    if let oldPath = pathsByUSR.updateValue(newPath, forKey: symbol.identifier.precise) {
                        assertionFailure("Should only have gathered one path per symbol ID. Found \(oldPath) and \(newPath) for the same USR.")
                    }
                }
                if includeDisambiguationForUnambiguousChildren || uniqueNodesWithChildren.count > 1 {
                    path += disambiguation.makeSuffix()
                }
                descend(node, accumulatedPath: path, updating: &pathsByUSR)
            }
        }
    }

    for node in modules {
        let modulePath = "/\(nameTransform(node.name))"
        pathsByUSR[node.name] = modulePath
        descend(node, accumulatedPath: modulePath, updating: &pathsByUSR)
    }

    assert(
        Set(pathsByUSR.values).count == pathsByUSR.keys.count,
        {
            let collisionDescriptions = pathsByUSR
                .reduce(into: [String: [String]](), { $0[$1.value, default: []].append($1.key) })
                .filter({ $0.value.count > 1 })
                .map { "\($0.key)\n\($0.value.map({ "  " + $0 }).joined(separator: "\n"))" }
            return """
            Disambiguated paths contain \(collisionDescriptions.count) collision(s):
            \(collisionDescriptions.joined(separator: "\n"))
            """
        }()
    )

    return pathsByUSR
}

private static func _disambiguatedValues(
    for elements: some Collection<Element>,
    includeLanguage: Bool,
    allowAdvancedDisambiguation: Bool
) -> [(value: PathHierarchy.Node, disambiguation: Disambiguation)] {
    var collisions: [(value: PathHierarchy.Node, disambiguation: Disambiguation)] = []
    // Assume that all elements will find a disambiguation (or close to it)
    collisions.reserveCapacity(elements.count)

    var remainingIDs = Set<ResolvedIdentifier>()
    remainingIDs.reserveCapacity(elements.count)
    for element in elements {
        guard let id = element.node.identifier else { continue }
        remainingIDs.insert(id)
    }

    // Kind disambiguation is the most readable, so we start by checking if any element has a unique kind.
    let groupedByKind = [String?: [Element]](grouping: elements, by: \.kind)
    for (kind, elements) in groupedByKind where elements.count == 1 && kind != nil {
        let element = elements.first!
        if includeLanguage, let language = element.node.languages.min() {
            collisions.append((value: element.node, disambiguation: .kind("\(language.linkDisambiguationID).\(kind!)")))
        } else {
            collisions.append((value: element.node, disambiguation: .kind(kind!)))
        }
        remainingIDs.remove(element.node.identifier)
    }
    if remainingIDs.isEmpty {
        return collisions
    }

    if allowAdvancedDisambiguation {
        let elementsThatSupportAdvancedDisambiguation = elements.filter { !$0.node.isExcludedFromAdvancedLinkDisambiguation }

        // Next, if a symbol returns a tuple with a unique number of values, disambiguate by that (without specifying what those arguments are)
        collisions += _disambiguateByTypeSignature(
            elementsThatSupportAdvancedDisambiguation,
            types: \.returnTypes,
            makeDisambiguation: { _, disambiguatingTypeNames in
                .returnTypes(disambiguatingTypeNames)
            },
            remainingIDs: &remainingIDs
        )
        if remainingIDs.isEmpty {
            return collisions
        }

        collisions += _disambiguateByTypeSignature(
            elementsThatSupportAdvancedDisambiguation,
            types: \.parameterTypes,
            makeDisambiguation: { _, disambiguatingTypeNames in
                .parameterTypes(disambiguatingTypeNames)
            },
            remainingIDs: &remainingIDs
        )
        if remainingIDs.isEmpty {
            return collisions
        }

        collisions += _disambiguateByTypeSignature(
            elementsThatSupportAdvancedDisambiguation,
            types: { element in
                guard let parameterTypes = element.parameterTypes,
                      !parameterTypes.isEmpty,
                      let returnTypes = element.returnTypes
                else {
                    return nil
                }
                return parameterTypes + returnTypes
            },
            makeDisambiguation: { element, disambiguatingTypeNames in
                let numberOfReturnTypes = element.returnTypes?.count ?? 0
                return .mixedTypes(parameterTypes: disambiguatingTypeNames.dropLast(numberOfReturnTypes), returnTypes: disambiguatingTypeNames.suffix(numberOfReturnTypes))
            },
            remainingIDs: &remainingIDs
        )
        if remainingIDs.isEmpty {
            return collisions
        }
    }

    for element in elements where remainingIDs.contains(element.node.identifier) {
        collisions.append((value: element.node, disambiguation: element.hash.map { .hash($0) } ?? .none))
    }
    return collisions
}

private static func _disambiguateByTypeSignature(
    _ elements: [Element],
    types: (Element) -> [String]?,
    makeDisambiguation: (Element, [String]) -> Disambiguation,
    remainingIDs: inout Set<ResolvedIdentifier>
) -> [(value: PathHierarchy.Node, disambiguation: Disambiguation)] {
    var collisions: [(value: PathHierarchy.Node, disambiguation: Disambiguation)] = []
    // Assume that all elements will find a disambiguation (or close to it)
    collisions.reserveCapacity(elements.count)

    typealias ElementAndTypeNames = (element: Element, typeNames: [String])
    var groupedByTypeCount: [Int: [ElementAndTypeNames]] = [:]
    for element in elements {
        guard let typeNames = types(element) else { continue }

        groupedByTypeCount[typeNames.count, default: []].append((element, typeNames))
    }

    for (numberOfTypeNames, elementAndTypeNamePairs) in groupedByTypeCount {
        guard elementAndTypeNamePairs.count > 1 else {
            // Only one element has this number of types. Disambiguate with only underscores.
            let (element, _) = elementAndTypeNamePairs.first!
            guard remainingIDs.remove(element.node.identifier) != nil else {
                continue // Don't disambiguate the same element more than once
            }
            collisions.append((value: element.node, disambiguation: makeDisambiguation(element, .init(repeating: "_", count: numberOfTypeNames))))
            continue
        }

        guard numberOfTypeNames > 0 else {
            continue // Need at least one type name to disambiguate (when there are multiple elements without parameters or return values)
        }

        let suggestedDisambiguations = minimalSuggestedDisambiguation(forOverloadsAndTypeNames: elementAndTypeNamePairs)

        for (pair, disambiguation) in zip(elementAndTypeNamePairs, suggestedDisambiguations) {
            guard let disambiguation else {
                continue // This element can't be uniquely disambiguated using these types
            }
            guard remainingIDs.remove(pair.element.node.identifier) != nil else {
                continue // Don't disambiguate the same element more than once
            }
            collisions.append((value: pair.element.node, disambiguation: makeDisambiguation(pair.element, disambiguation)))
        }
    }
    return collisions
}

private static func _minimalSuggestedDisambiguationForFewParameters(typeNames: consuming Table<String>) -> [[String]?] {
    /// A specialized set-algebra type that only stores the possible values `0 ..< 64`.
    ///
    /// This specialized implementation is _not_ suitable as a general purpose set-algebra type.
    /// However, because the code in this file only works with consecutive sequences of very small integers (most likely `0 ..< 16` and increasingly less likely the higher the number),
    /// and because the the sets of those integers is frequently accessed in loops, a specialized implementation addresses bottlenecks in `_minimalSuggestedDisambiguation(...)`.
    typealias IntSet = _FixedSizeBitSet<UInt64>

    // We find the minimal suggested type-signature disambiguation in two steps.
    //
    // First, we compute which type names occur in which overloads.
    // For example, these type names (left) occur in these overloads (right).
    //
    //   String   Int  Double                [0  ]   [012]   [01 ]
    //   String?  Int  Double                [ 12]   [012]   [01 ]
    //   String?  Int  Float                 [ 12]   [012]   [  2]
    let table = Table<IntSet>(width: typeNames.size.width, height: typeNames.size.height) { buffer in
        for column in typeNames.columnIndices {
            // When a type name is common across multiple overloads we don't need to recompute that information.
            // For example, consider a column of these 5 type names: ["Int", "Double", "Int", "Bool", "Double"].
            //
            // For the first type name ("Int"), we don't know anything about the other rows yet, so we check all 5.
            // This finds that "Int" occurs in both rows 0 and row 2. This information tells us that:
            //  - we can assign `[0 2  ]` to both those rows
            //  - we we don't need to check either of those rows again for the other type names.
            //
            // Thus, for the next type name ("Double"), we know that it's not in row 0 or 2, so we only need to check rows 1, 3, and 4.
            // This finds that "Double" occurs in both rows 1 and row 4, so we can assign `[ 1  4]` to both rows and don't check them again.
            //
            // Finally, for the third type name ("Bool") we know that it's not in rows 0, 1, 2, or 4, so we only need to check row 3.
            // Since this is the only row to check we can assign `[   3 ]` to it without iterating over any other rows.
            //
            // With no more rows to check we have found which type names occur in which overloads for every type name in this column.

            // At the start we need to consider every row
            var rowsToCheck = IntSet(typeNames.rowIndices)
            while !rowsToCheck.isEmpty {
                // Find all the rows with this type name
                var iterator = rowsToCheck.makeIterator()
                let currentRow = iterator.next()! // Verified to not be empty above.
                let typeName = typeNames[currentRow, column]

                var rowsWithThisTypeName = IntSet()
                rowsWithThisTypeName.insert(currentRow) // We know that the type name exist on the current row
                // Check all the other (unchecked rows)
                while let row = iterator.next() {
                    guard typeNames[row, column] == typeName else { continue }
                    rowsWithThisTypeName.insert(row)
                }

                // Once we've found which rows have this type name we can assign all of them...
                for row in rowsWithThisTypeName {
                    // Assign all the rows ...
                    buffer.initializeElementAt(row: row, column: column, to: rowsWithThisTypeName)
                }
                // ... and we can remove them from `rowsToCheck` so we don't check them again for the next type name.
                rowsToCheck.subtract(rowsWithThisTypeName)
            }
        }
    }

    // Second, iterate over each overload and try different combinations of type names to find the shortest disambiguation.
    //
    // To reduce unnecessary work in the iteration, we precompute which type name combinations are meaningful to check.

    // Check if any columns are common for all overloads. Those type names won't meaningfully disambiguate any overload.
    let allOverloads = IntSet(typeNames.rowIndices)
    let typeNameIndicesToCheck = IntSet(typeNames.columnIndices.filter {
        // It's sufficient to check the first row because this column has to be the same for all rows
        table[0, $0] != allOverloads
    })

    guard !typeNameIndicesToCheck.isEmpty else {
        // Every type name is common across all overloads.
        // Return `nil` for each overload to indicate that none of them can be disambiguated using these type names.
        return .init(repeating: nil, count: typeNames.size.width)
    }

    // Create a sequence of type name combinations with increasing number of type names in each combination.
    let typeNameCombinationsToCheck = typeNameIndicesToCheck.allCombinationsOfValues()

    return typeNames.rowIndices.map { row in
        var shortestDisambiguationSoFar: (indicesToInclude: IntSet, length: Int)? = nil

        // To determine the fewest and shortest disambiguation for each overload, we check combinations with increasing number of type names.
        // This explanation uses letters for type names occurrences to help distinguish them from the combinations of type names to check.
        //
        // For example, consider these type names from before (left) which occur in these overloads (right):
        //
        //   String   Int  Double                [A  ]   [ABC]   [AB ]
        //   String?  Int  Double                [ BC]   [ABC]   [AB ]
        //   String?  Int  Float                 [ BC]   [ABC]   [  C]
        //
        // With three different type names, the full list of combinations to check would be:
        //
        //   [0  ] [ 1 ] [  2] [01 ] [0 2] [ 12] [012]
        //
        // However, because the second type name [ 1 ] is known to be the same in all overloads, we can ignore any combination that includes it.
        // This reduces the possible combinations to check down to:
        //
        //   [0  ]  ___  [  2]  ___  [0 2]  ___  ___
        //
        // For the first overload, we start by checking if the type names at [0  ], which is [A  ] can disambiguate the overload.
        // Because [A  ] only contains one element, it can disambiguate the first overload. We calculate its length and keep track of this disambiguation.
        // Next, we check the type names at [  0], which is [AB ] for the first overload. This doesn't disambiguate the overload.
        // Next, we look at the type names at [0 2]. Because these are two type names and we already have a disambiguation with one type name,
        // we break out of the loop and return the type names at [0  ] as the disambiguation for this overload ("String", "_", "_").
        //
        // For the second overload, we start over and check type names at [0  ], which is [ BC], can disambiguate the overload.
        // It doesn't, so we check if the type names at [  2], which is [AB ], can disambiguate the second overload.
        // It also doesn't, so we check the if the type names at [0 2], which are [ BC] and [AB ], disambiguates the second overload.
        // The intersection of [ BC] and [AB ] is [ B ] which only has one value, so it does disambiguate the overload.
        // So, we break out of the loop and return the type names at [0 2] as the disambiguation for the second overload ("String?", "_", "Double").
        //
        // The third overload works much like the first overload. The type names at [  2], which is [  C], disambiguates the overload.
        // So, we break before checking [0 2]--which would include more type names--and return the type names at [  2] as the disambiguation ("_", "_", "Float").

        for typeNamesToInclude in typeNameCombinationsToCheck {
            // Stop if we've already found a disambiguating combination using fewer type names than this.
            guard typeNamesToInclude.count <= (shortestDisambiguationSoFar?.indicesToInclude.count ?? .max) else {
                break
            }

            // Compute which other overloads this combinations of type names also could refer to.
            var iterator = typeNamesToInclude.makeIterator()
            let firstTypeNameToInclude = iterator.next()! // The generated `typeNamesToInclude` is never empty.
            let overlap = IteratorSequence(iterator).reduce(into: table[row, firstTypeNameToInclude]) { accumulatedOverlap, index in
                accumulatedOverlap.formIntersection(table[row, index])
            }

            guard overlap.count == 1 else {
                // This combination of parameters doesn't disambiguate the result
                continue
            }

            // Track the combined length of this combination of type names in case another combination (with the same number of type names) is shorter.
            let length = typeNamesToInclude.reduce(0) { accumulatedLength, index in
                // It's faster to check the number of UTF8 code units.
                // This disfavors non-UTF8 type names, but those could be harder to read/write so neither length is right or wrong here.
                accumulatedLength + typeNames[row, index].utf8.count
            }
            if length < (shortestDisambiguationSoFar?.length ?? .max) {
                shortestDisambiguationSoFar = (IntSet(typeNamesToInclude), length)
            }
        }

        guard let (indicesToInclude, _) = shortestDisambiguationSoFar else {
            // This overload can't be uniquely disambiguated by these type names
            return nil
        }

        // Found the fewest (and shortest) type names that uniquely disambiguate this overload.
        // Return the list of disambiguating type names or "_" for an unused type name.
        return typeNames.columnIndices.map {
            indicesToInclude.contains($0) ? typeNames[row, $0] : "_"
        }
    }
}

func disambiguatedRelativeLinksForDescendants(of reference: ResolvedTopicReference) -> [ResolvedTopicReference: (link: String, hasDisambiguation: Bool)] {
    guard let nodeID = resolvedReferenceMap[reference] else { return [:] }

    let links = pathHierarchy.disambiguatedChildLinks(of: nodeID)
    var result = [ResolvedTopicReference: (link: String, hasDisambiguation: Bool)]()
    result.reserveCapacity(links.count)
    for (id, link) in links {
        guard let reference = resolvedReferenceMap[id] else { continue }
        result[reference] = link
    }
    return result
}

