static func layeredRoutes(
    ids: [String],
    sizes: [String: CGSize],
    layeringEdges: [(String, String)],
    routingEdges: [(from: String, to: String)],
    layerGap: CGFloat,
    nodeGap: CGFloat,
    margin: CGFloat,
    edgeLabelSizes: [CGSize?]? = nil
) -> (frames: [String: CGRect], size: CGSize, routes: [[CGPoint]], labelAnchors: [CGPoint?]) {
    let layerBack = backEdgeIndices(ids: ids, edges: layeringEdges)
    let forward = layeringEdges.enumerated().filter { !layerBack.contains($0.offset) }.map(\.element)
    let layerOf = assignLayers(ids: ids, edges: forward)
    let layerCount = (layerOf.values.max() ?? 0) + 1

    // Dummy nodes for every routing edge spanning more than one layer.
    var layers: [[String]] = Array(repeating: [], count: layerCount)
    for id in ids where layerOf[id] != nil { layers[layerOf[id]!].append(id) }
    var allSizes = sizes
    var chains: [[String]] = []
    var segmentEdges: [(String, String)] = []
    var dummies: Set<String> = []
    // Labeled edges between ADJACENT layers carry their text in the
    // inter-layer gap; grow each gap to fit the tallest such label so the
    // chip never crowds the boxes above or below it.
    var gapExtra = [CGFloat](repeating: 0, count: max(layerCount, 1))
    if let edgeLabelSizes {
        for (index, edge) in routingEdges.enumerated() {
            guard let labelSize = edgeLabelSizes[index],
                  let lu = layerOf[edge.from], let lv = layerOf[edge.to],
                  abs(lu - lv) == 1 else { continue }
            let gap = min(lu, lv)
            gapExtra[gap] = max(gapExtra[gap], labelSize.height + 6)
        }
    }
    for (index, edge) in routingEdges.enumerated() {
        guard let lu = layerOf[edge.from], let lv = layerOf[edge.to] else { chains.append([]); continue }
        let lo = min(lu, lv), hi = max(lu, lv)
        if hi - lo <= 1 {
            chains.append([edge.from, edge.to])
            segmentEdges.append((edge.from, edge.to))
            continue
        }
        var midByLayer: [(layer: Int, id: String)] = []
        // ELK-style label reservation: the MEDIAN dummy of a labeled edge
        // is widened to the label's size, so ordering and Brandes-Köpf
        // reserve real horizontal space for the text instead of the label
        // being squeezed in afterwards. `placeRunLabels` (below) then anchors
        // the caption on the resulting straight channel.
        let labelSize = edgeLabelSizes?[index] ?? nil
        let medianLayer = (lo + 1 + hi - 1) / 2
        for layer in (lo + 1)...(hi - 1) {
            let dummy = "\u{a7}b\(index).\(layer)"
            layers[layer].append(dummy)
            if let labelSize, layer == medianLayer {
                allSizes[dummy] = CGSize(width: max(16, labelSize.width + 8), height: 1)
            } else {
                allSizes[dummy] = CGSize(width: 16, height: 1)
            }
            dummies.insert(dummy)
            midByLayer.append((layer, dummy))
        }
        let mids = (lu < lv ? midByLayer : midByLayer.reversed()).map(\.id)
        let chain = [edge.from] + mids + [edge.to]
        chains.append(chain)
        for k in 0..<(chain.count - 1) { segmentEdges.append((chain[k], chain[k + 1])) }
    }

    // Order, then assign x with Brandes–Köpf (top-down; cross axis is x) so
    // dummy channels and box columns align into straight runs.
    let ordered = barycenterOrder(layers: layers, edges: segmentEdges)
    var breadth: [String: CGFloat] = [:]
    for layer in ordered { for id in layer { breadth[id] = allSizes[id]?.width ?? 0 } }
    var xCenter = brandesKoepfX(
        layers: ordered, segments: segmentEdges, breadth: breadth,
        dummies: dummies, minGap: nodeGap)
    // Same near-alignment jog fix as the flowchart pipeline: BK's
    // balancing leaves single-parent chains a few points off centre.
    straightenChains(layers: ordered, segments: segmentEdges,
                     breadth: breadth, minGap: nodeGap, center: &xCenter)
    var minCross = CGFloat.greatestFiniteMagnitude
    var maxCross = -CGFloat.greatestFiniteMagnitude
    for layer in ordered {
        for id in layer {
            let w = allSizes[id]?.width ?? 0
            let c = xCenter[id] ?? 0
            minCross = min(minCross, c - w / 2)
            maxCross = max(maxCross, c + w / 2)
        }
    }
    let shiftX = margin - (minCross.isFinite ? minCross : 0)
    let crossExtent = maxCross > minCross ? maxCross - minCross : 0

    var frames: [String: CGRect] = [:]
    var y = margin
    for (layerIndex, layer) in ordered.enumerated() {
        let layerHeight = layer.map { allSizes[$0]?.height ?? 0 }.max() ?? 0
        for id in layer {
            let size = allSizes[id] ?? .zero
            let cx = (xCenter[id] ?? 0) + shiftX
            frames[id] = CGRect(x: cx - size.width / 2, y: y, width: size.width, height: size.height)
        }
        y += layerHeight + layerGap
        if layerIndex < gapExtra.count { y += gapExtra[layerIndex] }
    }

    // Antiparallel detection: an edge whose reverse also exists must not
    // share the reverse's column, or the two render as one line.
    var directedPairs = Set<String>()
    for edge in routingEdges { directedPairs.insert(edge.from + "\u{1}" + edge.to) }

    // Route each edge through its chain waypoints.
    var routes: [[CGPoint]] = []
    for (ci, chain) in chains.enumerated() {
        guard chain.count >= 2, let fromFrame = frames[chain[0]], let toFrame = frames[chain[chain.count - 1]] else {
            routes.append([.zero, .zero]); continue
        }
        // Self-loop (an edge from a box back to itself, e.g. an ER
        // "subcategory of" parent_id): route it as a small loop off the
        // right side, never a straight line through the box interior. The
        // top/bottom bars stay short (a wider loop would gore a neighbour);
        // the caption rides the vertical return run, which we grow to the
        // label height plus a stub on each side so a word like "retry" isn't
        // crammed onto the default span (`label-crowds-edge`).
        if chain[0] == chain[chain.count - 1] {
            let f = fromFrame
            let ext: CGFloat = 24
            let labelH = (edgeLabelSizes?[ci] ?? nil)?.height ?? 0
            let vHalf = max(min(f.height * 0.24, 13), labelH / 2 + edgeLabelStub)
            let yHi = f.midY - vHalf
            let yLo = f.midY + vHalf
            routes.append([
                CGPoint(x: f.maxX, y: yHi),
                CGPoint(x: f.maxX + ext, y: yHi),
                CGPoint(x: f.maxX + ext, y: yLo),
                CGPoint(x: f.maxX, y: yLo),
            ])
            continue
        }
        // Same layer → route the short way through side faces, UNLESS the
        // direct line would cross another box sitting between the two: then
        // dip into the gap just below the row and cross there instead of
        // straight through the intervening box.
        if abs(fromFrame.midY - toFrame.midY) < 1 {
            let right = toFrame.midX >= fromFrame.midX
            let start = CGPoint(x: right ? fromFrame.maxX : fromFrame.minX, y: fromFrame.midY)
            let end = CGPoint(x: right ? toFrame.minX : toFrame.maxX, y: toFrame.midY)
            let lo = min(start.x, end.x), hi = max(start.x, end.x)
            let blocked = frames.contains { id, fr in
                id != chain[0] && id != chain[chain.count - 1] && !dummies.contains(id)
                    && abs(fr.midY - fromFrame.midY) < 1
                    && fr.minX < hi - 2 && fr.maxX > lo + 2
            }
            if blocked {
                let dy = fromFrame.maxY + 16
                routes.append([start, CGPoint(x: start.x, y: dy), CGPoint(x: end.x, y: dy), end])
            } else {
                routes.append([start, end])
            }
            continue
        }
        let dummyCenters = chain[1..<(chain.count - 1)].compactMap { frames[$0].map { CGPoint(x: $0.midX, y: $0.midY) } }
        // Straight column: when the two boxes' x-ranges overlap and there
        // are no dummies to route around, attach both ends at one shared x
        // so the edge is a single straight segment — no tiny S-hook from a
        // near-alignment offset.
        let overlapLo = max(fromFrame.minX, toFrame.minX) + 4
        let overlapHi = min(fromFrame.maxX, toFrame.maxX) - 4
        if dummyCenters.isEmpty, overlapLo <= overlapHi {
            var x = min(max((fromFrame.midX + toFrame.midX) / 2, overlapLo), overlapHi)
            let down = toFrame.midY >= fromFrame.midY
            // If a reverse edge exists between the same pair, place the two
            // as a centred block a full separation apart (not an independent
            // ±offset, which the overlap clamp then compresses), so they read
            // as two clear parallel lines (e.g. state "connect"/"fail").
            if directedPairs.contains(chain[chain.count - 1] + "\u{1}" + chain[0]) {
                let half = min(boxAntiparallelSep / 2, (overlapHi - overlapLo) / 2)
                let center = min(max(x, overlapLo + half), overlapHi - half)
                x = center + (down ? half : -half)
            }
            let start = CGPoint(x: x, y: down ? fromFrame.maxY : fromFrame.minY)
            let end = CGPoint(x: x, y: down ? toFrame.minY : toFrame.maxY)
            routes.append([start, end])
            continue
        }
        let firstNext = dummyCenters.first ?? CGPoint(x: toFrame.midX, y: toFrame.midY)
        let lastPrev = dummyCenters.last ?? CGPoint(x: fromFrame.midX, y: fromFrame.midY)
        func attach(_ f: CGRect, towardX: CGFloat, bottom: Bool) -> CGPoint {
            CGPoint(x: min(max(towardX, f.minX + 4), f.maxX - 4), y: bottom ? f.maxY : f.minY)
        }
        let start = attach(fromFrame, towardX: firstNext.x, bottom: firstNext.y >= fromFrame.midY)
        let end = attach(toFrame, towardX: lastPrev.x, bottom: lastPrev.y > toFrame.midY)
        let points = routePolyline([start] + dummyCenters + [end], horizontal: false)
        routes.append(points)
    }

    // Push horizontal runs out of box bands. A cross-layer edge's jog is
    // placed at the midpoint between its dummy and the target, which for a
    // TALL intermediate box lands inside it (class "contains" jogging at
    // y=272 through Customer, whose band is y179–300). Move any interior
    // horizontal segment that crosses a box to the nearest clear y — the
    // connecting vertical legs sit in dummy channels, so lengthening them
    // stays clear. Routes with no crossing are untouched.
    let realFrames = ids.compactMap { dummies.contains($0) ? nil : frames[$0] }
    for ri in routes.indices {
        var pts = routes[ri]
        guard pts.count >= 4 else { continue }
        var i = 1
        while i < pts.count - 2 {
            let a = pts[i], b = pts[i + 1]
            if abs(a.y - b.y) < 0.5 && abs(a.x - b.x) > 1 {
                let lo = min(a.x, b.x) + 2, hi = max(a.x, b.x) - 2
                let pad: CGFloat = 16
                func crosses(_ yy: CGFloat) -> Bool {
                    realFrames.contains { $0.minY + 2 < yy && $0.maxY - 2 > yy && $0.minX < hi && $0.maxX > lo }
                }
                // A destination y must clear every crossed box by `pad`, so the
                // run sits well inside the gap rather than skimming a border.
                func clearWithPadding(_ yy: CGFloat) -> Bool {
                    !realFrames.contains { $0.minY - pad < yy && $0.maxY + pad > yy && $0.minX < hi && $0.maxX > lo }
                }
                if crosses(a.y) {
                    var moved: CGFloat?
                    var d: CGFloat = 4
                    while d <= 300 {
                        for cand in [a.y + d, a.y - d] where clearWithPadding(cand) { moved = cand; break }
                        if moved != nil { break }
                        d += 4
                    }
                    if let ny = moved { pts[i].y = ny; pts[i + 1].y = ny }
                }
            }
            i += 1
        }
        routes[ri] = pts
    }

    // Same guarantee the flowchart router gives: no two edges' runs may
    // coincide on one track. Catches long/back-edge channels that land on a
    // box column (the antiparallel block above only covers adjacent pairs).
    separateRuns(&routes, horizontal: false, minSep: boxAntiparallelSep)

    var routeMaxX = crossExtent + margin
    for pts in routes { for p in pts { routeMaxX = max(routeMaxX, p.x) } }
    var size = CGSize(width: max(crossExtent, routeMaxX - margin) + margin * 2, height: y - layerGap + margin)
    // Place every caption on the longest clean straight run of its final
    // route, collision-avoiding node boxes, other captions, bends, and
    // crossings — the same run-based placement the flowchart pipeline uses,
    // so a state/class/ER label never lands on a corner or a junction, and
    // sibling adjacent-layer labels that share an inter-layer gap slide
    // apart instead of stacking on one midpoint. (The reserved median-dummy
    // channel and the grown gap give this pass the room it needs.)
    let realFrameList = ids.compactMap { dummies.contains($0) ? nil : frames[$0] }
    let labelSizes: [CGSize?] = routingEdges.indices.map { edgeLabelSizes?[$0] ?? nil }
    let labelAnchors = placeRunLabels(routes: routes, labelSizes: labelSizes,
                                      nodeFrames: realFrameList)
    // Grow the canvas for any caption nudged past the content box — the same
    // post-placement expansion layoutFlat performs — so a label on the
    // rightmost/bottom-most run (or a perpendicular nudge off it) is never
    // clipped or flagged off-canvas.
    for (i, anchor) in labelAnchors.enumerated() {
        guard let lp = anchor, let sz = labelSizes[i] else { continue }
        size.width = max(size.width, lp.x + sz.width / 2 + margin)
        size.height = max(size.height, lp.y + sz.height / 2 + margin)
    }
    // Dummy frames are internal scaffolding — don't leak them.
    for dummy in dummies { frames[dummy] = nil }
    return (frames, size, routes, labelAnchors)
}

private func stripGraphArt(_ line: String) -> String {
    let art: Set<Character> = ["*", "|", "/", "\\", "_", " ", "\t"]
    var idx = line.startIndex
    while idx < line.endIndex, art.contains(line[idx]) { idx = line.index(after: idx) }
    return String(line[idx...]).trimmingCharacters(in: .whitespaces)
}

private static func openSubgraph(
    _ line: String,
    into subgraphs: inout [String: Flowchart.Subgraph],
    order: inout [String],
    stack: [String],
    reserved: Set<String>,
    anonCount: inout Int
) -> String {
    /// A synthesized id (`§sub0`, `§sub1`, …) no subgraph has, and no
    /// header in the chart names (`reserved`), whatever the order.
    func fresh() -> String {
        while subgraphs["\u{a7}sub\(anonCount)"] != nil || reserved.contains("\u{a7}sub\(anonCount)") { anonCount += 1 }
        defer { anonCount += 1 }
        return "\u{a7}sub\(anonCount)"
    }
    let header = subgraphHeader(line)
    var id = header.id ?? fresh()
    let label = header.label
    // A closed subgraph's id, used again, reopens it, as in mermaid: its
    // first title and direction stand and the block adds members. Only a
    // named id can (a synthesized one is always new); one still open (a
    // subgraph inside itself) gets a fresh id instead.
    if subgraphs[id] != nil {
        if !stack.contains(id) { return id }
        id = fresh()
    }
    subgraphs[id] = Flowchart.Subgraph(id: id, label: labelText(label))
    order.append(id)
    return id
}

func fresh() -> String {
    while subgraphs["\u{a7}sub\(anonCount)"] != nil || reserved.contains("\u{a7}sub\(anonCount)") { anonCount += 1 }
    defer { anonCount += 1 }
    return "\u{a7}sub\(anonCount)"
}

static func parseState(body: [String]) -> StateDiagram? {
    // Composite parsing (and the layout that mirrors it) recurses once per
    // `state X {` nesting level. A linear pre-scan bounds that depth so
    // adversarial input can't overflow the stack — past the cap the block
    // degrades to the tidy styled-source card.
    var depth = 0, maxDepth = 0
    for line in body {
        if line.hasPrefix("state "), line.hasSuffix("{") { depth += 1; maxDepth = max(maxDepth, depth) }
        if line == "}" { depth = max(0, depth - 1) }
    }
    guard maxDepth <= 32 else { return nil }

    var index = 0
    var scopeCounter = 0
    let direction = detectStateDirection(body)

    // Recursively parses one brace scope, consuming lines until its
    // closing `}` (or end of input for the root). `scopeID` disambiguates
    // this scope's synthetic `[*]` terminals from every other scope's.
    func parseScope(scopeID: String) -> StateDiagram {
        var nodes: [String: StateDiagram.Node] = [:]
        var order: [String] = []
        var edges: [StateDiagram.Edge] = []
        var annotations: [String: StateDiagram.Kind] = [:]  // id → choice/fork/join

        func note(id: String, label: String, kind: StateDiagram.Kind) {
            if let existing = nodes[id] {
                // Upgrade a bare reference to a labelled / composite node.
                if existing.label == existing.id && (label != id || !isSimple(kind)) {
                    nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
                } else if isComposite(kind) {
                    nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
                }
            } else {
                nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
                order.append(id)
            }
        }

        // Resolves a transition endpoint token to a node id, minting a
        // scope-local terminal for `[*]`.
        func endpoint(_ token: String, isSource: Bool) -> String? {
            let trimmed = token.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty else { return nil }
            if trimmed == "[*]" {
                let id = isSource ? "\(scopeID)__start" : "\(scopeID)__end"
                note(id: id, label: "", kind: isSource ? .start : .end)
                return id
            }
            guard trimmed.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }) else { return nil }
            note(id: trimmed, label: trimmed, kind: .simple)
            return trimmed
        }

        while index < body.count {
            let line = body[index]
            index += 1

            if line == "}" { break }                       // close this scope
            if line.hasPrefix("direction") { continue }    // handled globally
            if line.hasPrefix("note") || line.hasPrefix("Note") { continue }

            // `state X { ` opens a composite — recurse.
            if line.hasPrefix("state "), line.hasSuffix("{") {
                let inner = String(line.dropFirst("state ".count).dropLast())
                    .trimmingCharacters(in: .whitespaces)
                let (id, label) = stateNameAndLabel(inner)
                scopeCounter += 1
                let child = parseScope(scopeID: "s\(scopeCounter)_")
                nodes[id] = StateDiagram.Node(id: id, label: label, kind: .composite(child))
                if !order.contains(id) { order.append(id) }
                continue
            }

            // `state X <<choice>>` / `<<fork>>` / `<<join>>` annotations.
            if line.hasPrefix("state "), let annotationRange = line.range(of: "<<") {
                let id = String(line[line.index(line.startIndex, offsetBy: "state ".count)..<annotationRange.lowerBound])
                    .trimmingCharacters(in: .whitespaces)
                let annotation = line[annotationRange.lowerBound...]
                let kind: StateDiagram.Kind? = annotation.contains("choice") ? .choice
                    : annotation.contains("fork") ? .fork
                    : annotation.contains("join") ? .join : nil
                if let kind, !id.isEmpty {
                    annotations[id] = kind
                    note(id: id, label: id, kind: kind)
                }
                continue
            }

            // `state "Long description" as s2`
            if line.hasPrefix("state ") {
                let declaration = String(line.dropFirst("state ".count))
                if let asRange = declaration.range(of: " as ") {
                    let label = String(declaration[..<asRange.lowerBound])
                        .trimmingCharacters(in: .whitespaces)
                        .trimmingCharacters(in: CharacterSet(charactersIn: "\""))
                    let id = String(declaration[asRange.upperBound...]).trimmingCharacters(in: .whitespaces)
                    if !id.isEmpty { note(id: id, label: label, kind: .simple) }
                } else {
                    let (id, label) = stateNameAndLabel(declaration.trimmingCharacters(in: .whitespaces))
                    if !id.isEmpty { note(id: id, label: label, kind: .simple) }
                }
                continue
            }

            if let arrowRange = line.range(of: "-->") {
                let left = String(line[..<arrowRange.lowerBound])
                var right = String(line[arrowRange.upperBound...])
                var label: String?
                if let colon = right.firstIndex(of: ":") {
                    label = String(right[right.index(after: colon)...]).trimmingCharacters(in: .whitespaces)
                    right = String(right[..<colon])
                }
                guard let from = endpoint(left, isSource: true),
                      let to = endpoint(right, isSource: false) else { continue }
                edges.append(StateDiagram.Edge(from: from, to: to, label: label))
                continue
            }

            // Bare state id on its own line.
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if !trimmed.isEmpty, trimmed.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }) {
                note(id: trimmed, label: trimmed, kind: .simple)
            }
        }

        // Apply any annotations that arrived after a node was first seen.
        for (id, kind) in annotations where nodes[id] != nil {
            nodes[id] = StateDiagram.Node(id: id, label: nodes[id]!.label == id ? id : nodes[id]!.label, kind: kind)
        }

        return StateDiagram(
            direction: direction,
            nodes: order.compactMap { nodes[$0] },
            edges: edges
        )
    }

    let root = parseScope(scopeID: "root_")
    guard !root.nodes.isEmpty else { return nil }
    return root
}

func parseScope(scopeID: String) -> StateDiagram {
    var nodes: [String: StateDiagram.Node] = [:]
    var order: [String] = []
    var edges: [StateDiagram.Edge] = []
    var annotations: [String: StateDiagram.Kind] = [:]  // id → choice/fork/join

    func note(id: String, label: String, kind: StateDiagram.Kind) {
        if let existing = nodes[id] {
            // Upgrade a bare reference to a labelled / composite node.
            if existing.label == existing.id && (label != id || !isSimple(kind)) {
                nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
            } else if isComposite(kind) {
                nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
            }
        } else {
            nodes[id] = StateDiagram.Node(id: id, label: label, kind: kind)
            order.append(id)
        }
    }

    // Resolves a transition endpoint token to a node id, minting a
    // scope-local terminal for `[*]`.
    func endpoint(_ token: String, isSource: Bool) -> String? {
        let trimmed = token.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return nil }
        if trimmed == "[*]" {
            let id = isSource ? "\(scopeID)__start" : "\(scopeID)__end"
            note(id: id, label: "", kind: isSource ? .start : .end)
            return id
        }
        guard trimmed.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }) else { return nil }
        note(id: trimmed, label: trimmed, kind: .simple)
        return trimmed
    }

    while index < body.count {
        let line = body[index]
        index += 1

        if line == "}" { break }                       // close this scope
        if line.hasPrefix("direction") { continue }    // handled globally
        if line.hasPrefix("note") || line.hasPrefix("Note") { continue }

        // `state X { ` opens a composite — recurse.
        if line.hasPrefix("state "), line.hasSuffix("{") {
            let inner = String(line.dropFirst("state ".count).dropLast())
                .trimmingCharacters(in: .whitespaces)
            let (id, label) = stateNameAndLabel(inner)
            scopeCounter += 1
            let child = parseScope(scopeID: "s\(scopeCounter)_")
            nodes[id] = StateDiagram.Node(id: id, label: label, kind: .composite(child))
            if !order.contains(id) { order.append(id) }
            continue
        }

        // `state X <<choice>>` / `<<fork>>` / `<<join>>` annotations.
        if line.hasPrefix("state "), let annotationRange = line.range(of: "<<") {
            let id = String(line[line.index(line.startIndex, offsetBy: "state ".count)..<annotationRange.lowerBound])
                .trimmingCharacters(in: .whitespaces)
            let annotation = line[annotationRange.lowerBound...]
            let kind: StateDiagram.Kind? = annotation.contains("choice") ? .choice
                : annotation.contains("fork") ? .fork
                : annotation.contains("join") ? .join : nil
            if let kind, !id.isEmpty {
                annotations[id] = kind
                note(id: id, label: id, kind: kind)
            }
            continue
        }

        // `state "Long description" as s2`
        if line.hasPrefix("state ") {
            let declaration = String(line.dropFirst("state ".count))
            if let asRange = declaration.range(of: " as ") {
                let label = String(declaration[..<asRange.lowerBound])
                    .trimmingCharacters(in: .whitespaces)
                    .trimmingCharacters(in: CharacterSet(charactersIn: "\""))
                let id = String(declaration[asRange.upperBound...]).trimmingCharacters(in: .whitespaces)
                if !id.isEmpty { note(id: id, label: label, kind: .simple) }
            } else {
                let (id, label) = stateNameAndLabel(declaration.trimmingCharacters(in: .whitespaces))
                if !id.isEmpty { note(id: id, label: label, kind: .simple) }
            }
            continue
        }

        if let arrowRange = line.range(of: "-->") {
            let left = String(line[..<arrowRange.lowerBound])
            var right = String(line[arrowRange.upperBound...])
            var label: String?
            if let colon = right.firstIndex(of: ":") {
                label = String(right[right.index(after: colon)...]).trimmingCharacters(in: .whitespaces)
                right = String(right[..<colon])
            }
            guard let from = endpoint(left, isSource: true),
                  let to = endpoint(right, isSource: false) else { continue }
            edges.append(StateDiagram.Edge(from: from, to: to, label: label))
            continue
        }

        // Bare state id on its own line.
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if !trimmed.isEmpty, trimmed.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }) {
            note(id: trimmed, label: trimmed, kind: .simple)
        }
    }

    // Apply any annotations that arrived after a node was first seen.
    for (id, kind) in annotations where nodes[id] != nil {
        nodes[id] = StateDiagram.Node(id: id, label: nodes[id]!.label == id ? id : nodes[id]!.label, kind: kind)
    }

    return StateDiagram(
        direction: direction,
        nodes: order.compactMap { nodes[$0] },
        edges: edges
    )
}

public static func diagnose(_ source: String) -> [ParseDiagnostic] {
    // Whole-source guards, in the same order parse() applies them.
    guard !source.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
        return [.init(severity: .error, line: nil, message: "source is empty")]
    }
    guard source.count <= maxTextSize else {
        return [.init(severity: .error, line: nil,
                      message: "source is \(source.count) characters; the cap is \(maxTextSize) (MermaidParser.maxTextSize)")]
    }

    // Locate the header: first line that isn't blank or a %% comment.
    let rawLines = source.split(separator: "\n", omittingEmptySubsequences: false)
        .map { $0.trimmingCharacters(in: .whitespaces) }
    guard let headerIndex = rawLines.firstIndex(where: { !$0.isEmpty && !$0.hasPrefix("%%") }) else {
        return [.init(severity: .error, line: nil, message: "source contains only comments/blank lines")]
    }
    let header = rawLines[headerIndex]
    let headerLine = headerIndex + 1
    let headerWord = String(header.split(separator: " ").first ?? "")

    if parse(source) != nil { return setAsideNotes(source) }

    // The header was recognized but the parse still failed: either the
    // flowchart edge cap, or a body the type parser couldn't use.
    if knownHeaders.contains(where: { header.hasPrefix(commonPrefixKey($0)) }) {
        if header.hasPrefix("graph") || header.hasPrefix("flowchart") {
            // Distinguish the edge cap from an empty/broken body.
            let statements = rawLines.filter { !$0.isEmpty && !$0.hasPrefix("%%") }.flatMap(flowchartStatements)
            if let first = statements.first,
               let chart = parseFlowchart(header: first, body: Array(statements.dropFirst())),
               chart.edges.count > maxEdges {
                return [.init(severity: .error, line: nil,
                              message: "flowchart has \(chart.edges.count) edges; the cap is \(maxEdges) (MermaidParser.maxEdges)")]
            }
        }
        return [.init(severity: .error, line: headerLine,
                      message: "recognized '\(headerWord)' but the body produced no usable content — check the type's core syntax")]
    }

    // Unknown header — suggest the nearest known one.
    if let suggestion = nearestHeader(to: headerWord) {
        return [.init(severity: .error, line: headerLine,
                      message: "unknown diagram type '\(headerWord)' — did you mean '\(suggestion)'?")]
    }
    return [.init(severity: .error, line: headerLine,
                  message: "unknown diagram type '\(headerWord)'")]
}

private func skip(_ words: [String]) {
    while i < t.count, t[i].word, words.contains(t[i].text.lowercased()) { i += 1 }
}

static func layout(_ ast: ArchitectureAST) -> PositionedArchitecture {
    // 1. Assign each service/junction a grid cell.
    var pos: [String: Cell] = [:]
    var occupied: Set<Cell> = []

    // Adjacency for BFS (only "node ↔ node" edges; group-marked endpoints still constrain the
    // underlying nodes, which is a reasonable approximation).
    var adjacency: [String: [(neighbour: String, fromSide: ArchSide)]] = [:]
    for edge in ast.edges {
        guard ast.services[edge.lhs.id] != nil, ast.services[edge.rhs.id] != nil else { continue }
        adjacency[edge.lhs.id, default: []].append((edge.rhs.id, edge.lhs.side))
        adjacency[edge.rhs.id, default: []].append((edge.lhs.id, edge.rhs.side))
    }

    func place(_ id: String, at cell: Cell) {
        var c = cell
        // Resolve collisions by stepping one more cell along the original direction, then by a
        // small spiral. This keeps "intent" while never overlapping.
        if occupied.contains(c) {
            var found = false
            for radius in 1...6 {
                for (dc, dr) in [(radius, 0), (0, radius), (-radius, 0), (0, -radius),
                                 (radius, radius), (-radius, radius), (radius, -radius), (-radius, -radius)] {
                    let cand = Cell(c: cell.c + dc, r: cell.r + dr)
                    if !occupied.contains(cand) { c = cand; found = true; break }
                }
                if found { break }
            }
        }
        pos[id] = c
        occupied.insert(c)
    }

    // BFS over connected components, in declaration order for determinism.
    var visited: Set<String> = []
    var nextFreeColForComponents = 0
    for startID in ast.serviceOrder where !visited.contains(startID) {
        guard adjacency[startID] != nil else { continue }   // isolated nodes handled later
        // Anchor this component to the right of previous components.
        let anchor = Cell(c: nextFreeColForComponents, r: 0)
        place(startID, at: anchor)
        visited.insert(startID)
        var queue = [startID]
        var head = 0
        while head < queue.count {
            let u = queue[head]; head += 1
            guard let uCell = pos[u] else { continue }
            for (v, side) in adjacency[u] ?? [] where !visited.contains(v) {
                let (dc, dr) = side.gridDelta
                place(v, at: Cell(c: uCell.c + dc, r: uCell.r + dr))
                visited.insert(v)
                queue.append(v)
            }
        }
        // Advance the anchor column past this component's bbox.
        let maxC = occupied.map(\.c).max() ?? nextFreeColForComponents
        nextFreeColForComponents = maxC + 2
    }

    // 2. Isolated services: lay them out per group so group boxes don't collapse on top of each
    //    other. Members of a group with placed siblings go next to them; otherwise a fresh row.
    let maxRowSoFar = occupied.map(\.r).max() ?? 0
    var groupFreeRow: [String?: Int] = [:]   // immediate-group → next free row for stragglers
    for id in ast.serviceOrder where pos[id] == nil {
        let svc = ast.services[id]!
        let key = svc.groupID
        // Find a column anchor: near an already-placed sibling in the same group, else fresh.
        let siblingCells = ast.serviceOrder
            .filter { ast.services[$0]?.groupID == key }
            .compactMap { pos[$0] }
        let baseCol = siblingCells.map(\.c).min() ?? (nextFreeColForComponents)
        let baseRow = groupFreeRow[key] ?? (siblingCells.map(\.r).max().map { $0 + 1 } ?? (maxRowSoFar + 2))
        // Pack horizontally on `baseRow`.
        var col = baseCol
        while occupied.contains(Cell(c: col, r: baseRow)) { col += 1 }
        place(id, at: Cell(c: col, r: baseRow))
        groupFreeRow[key] = (groupFreeRow[key] ?? baseRow)
        if key == nil { nextFreeColForComponents = max(nextFreeColForComponents, col + 2) }
    }

    // 3. Normalise grid to start at (0,0) and convert to pixel rects.
    let minC = pos.values.map(\.c).min() ?? 0
    let minR = pos.values.map(\.r).min() ?? 0
    func cellRect(_ cell: Cell) -> CGRect {
        let x = outerMargin + CGFloat(cell.c - minC) * (serviceW + cellGapX)
        let y = outerMargin + CGFloat(cell.r - minR) * (serviceH + cellGapY)
        return CGRect(x: x, y: y, width: serviceW, height: serviceH)
    }

    var nodes: [PositionedArchNode] = []
    var nodeRectByID: [String: CGRect] = [:]
    for id in ast.serviceOrder {
        guard let cell = pos[id], let svc = ast.services[id] else { continue }
        let full = cellRect(cell)
        let rect: CGRect
        if svc.isJunction {
            rect = CGRect(center: full.center, size: .zero)
        } else {
            rect = full
        }
        nodeRectByID[id] = rect
        nodes.append(PositionedArchNode(id: id, rect: rect, title: svc.title, icon: svc.icon,
                                        isJunction: svc.isJunction, groupID: svc.groupID))
    }

    // 4. Group boxes — innermost first so a parent's box encloses child boxes.
    var depthOf: [String: Int] = [:]
    func depth(_ id: String) -> Int {
        if let d = depthOf[id] { return d }
        let d = (ast.groups[id]?.parentID).map { depth($0) + 1 } ?? 0
        depthOf[id] = d
        return d
    }
    // Build child lists.
    var childServices: [String: [String]] = [:]
    for (id, svc) in ast.services { if let g = svc.groupID { childServices[g, default: []].append(id) } }
    var childGroups: [String: [String]] = [:]
    for (id, g) in ast.groups { if let p = g.parentID { childGroups[p, default: []].append(id) } }

    var groupRectByID: [String: CGRect] = [:]
    func boundsFor(_ id: String) -> CGRect? {
        var rect: CGRect? = nil
        func add(_ r: CGRect) {
            guard r.width >= 0, r.height >= 0 else { return }
            rect = rect.map { $0.union(r) } ?? r
        }
        for s in childServices[id] ?? [] {
            if let r = nodeRectByID[s] { add(r.insetBy(dx: -2, dy: -2)) }
        }
        for child in childGroups[id] ?? [] {
            if let r = boundsFor(child) { add(r) }
        }
        return rect
    }

    var groups: [PositionedArchGroup] = []
    // Process deepest first so nested boxes are computed before their parents query them.
    let orderedGroupIDs = ast.groupOrder.sorted { depth($0) > depth($1) }
    for id in orderedGroupIDs {
        guard let g = ast.groups[id] else { continue }
        guard let inner = boundsFor(id) else { continue }
        let titleBlock = g.title.isEmpty ? CGSize.zero : TextMeasure.layout(g.title, font: groupTitleFont).size
        let titleHeight = titleBlock.height > 0 ? titleBlock.height + groupTitlePadding * 2 : 0
        let padded = inner.insetBy(dx: -groupPadding, dy: -groupPadding)
        let rect = CGRect(x: padded.minX, y: padded.minY - titleHeight,
                          width: max(padded.width, titleBlock.width + groupPadding * 2),
                          height: padded.height + titleHeight)
        groupRectByID[id] = rect
        groups.append(PositionedArchGroup(id: id, title: g.title, icon: g.icon, rect: rect,
                                          titleHeight: titleHeight, depth: depth(id)))
    }
    // Re-sort groups outermost→innermost for stable rendering.
    groups.sort { $0.depth < $1.depth }

    // 5. Route edges.
    var edges: [PositionedArchEdge] = []
    for edge in ast.edges {
        guard let lhsRect = rect(for: edge.lhs, nodeRects: nodeRectByID, groupRects: groupRectByID, ast: ast),
              let rhsRect = rect(for: edge.rhs, nodeRects: nodeRectByID, groupRects: groupRectByID, ast: ast) else {
            continue
        }
        let pts = route(from: lhsRect, side: edge.lhs.side, to: rhsRect, side: edge.rhs.side)
        edges.append(PositionedArchEdge(points: pts, arrowStart: edge.arrowLhs, arrowEnd: edge.arrowRhs))
    }

    // 6. Canvas size.
    var maxX: CGFloat = 0, maxY: CGFloat = 0
    var minX: CGFloat = .infinity, minY: CGFloat = .infinity
    func extend(_ r: CGRect) {
        minX = min(minX, r.minX); minY = min(minY, r.minY)
        maxX = max(maxX, r.maxX); maxY = max(maxY, r.maxY)
    }
    for n in nodes where !n.isJunction { extend(n.rect.insetBy(dx: 0, dy: -labelHeight())) }
    for g in groups { extend(g.rect) }
    for e in edges { for p in e.points { extend(CGRect(x: p.x, y: p.y, width: 0, height: 0)) } }
    if !minX.isFinite { minX = 0; minY = 0 }
    // Shift everything so the content starts at outerMargin.
    let dx = outerMargin - minX
    let dy = outerMargin - minY
    if dx != 0 || dy != 0 {
        for i in nodes.indices { nodes[i].rect = nodes[i].rect.offsetBy(dx: dx, dy: dy) }
        for i in groups.indices { groups[i].rect = groups[i].rect.offsetBy(dx: dx, dy: dy) }
        for i in edges.indices { edges[i].points = edges[i].points.map { CGPoint(x: $0.x + dx, y: $0.y + dy) } }
    }
    let size = CGSize(width: (maxX - minX) + outerMargin * 2,
                      height: (maxY - minY) + outerMargin * 2)
    return PositionedArchitecture(size: size, nodes: nodes, groups: groups, edges: edges)
}

private static func parseSubgraphHeader(_ stmt: String, state: inout ParserState, line lineNo: Int) throws {
    // Forms:
    //   subgraph id
    //   subgraph id [Title]
    //   subgraph "Title"
    //   subgraph id ["Long title"]
    var scanner = Scanner(string: stmt)
    _ = scanner.readIdentifier()    // consume "subgraph"
    scanner.skipSpaces()

    var id: String? = nil
    var title: String? = nil

    // Quoted title-only form: `subgraph "Title"`.
    if scanner.peek() == "\"" {
        title = scanner.readQuotedString()
    } else {
        id = scanner.readIdentifier()
        scanner.skipSpaces()
        if scanner.peek() == "[" {
            let (_, text) = scanner.readBracketGroup() ?? (.rect, "")
            title = text
        } else if scanner.peek() == "\"" {
            title = scanner.readQuotedString()
        }
    }

    let assignedID: String
    if let id { assignedID = id } else {
        state.subgraphAutoCounter += 1
        assignedID = "__subgraph\(state.subgraphAutoCounter)"
    }
    if state.subgraphs[assignedID] == nil {
        state.subgraphs[assignedID] = FlowSubgraph(id: assignedID, title: title ?? id,
                                                   nodeIDs: [], childSubgraphIDs: [],
                                                   parentID: state.currentSubgraph,
                                                   direction: nil)
        state.subgraphOrder.append(assignedID)
    }
    state.subgraphStack.append(assignedID)
}

private static func uniqueReverseId() -> String {
    os_unfair_lock_lock(&counterLock)
    defer { os_unfair_lock_unlock(&counterLock) }
    reverseIdCounter += 1
    return "rev\(reverseIdCounter)"
}

public static func uniqueId(_ prefix: String = "_") -> String {
    os_unfair_lock_lock(&counterLock)
    defer { os_unfair_lock_unlock(&counterLock) }
    _nodeIdCounter += 1
    return "\(prefix)\(_nodeIdCounter)"
}

private func identifiers(for nodes: [DependencyNode]) -> [String: String] {
    var identifiers: [String: String] = [:]
    var used: Set<String> = []

    for node in nodes {
        let base = sanitizeIdentifier(node.name)
        var identifier = base
        var suffix = 2
        while used.contains(identifier) {
            identifier = "\(base)_\(suffix)"
            suffix += 1
        }
        identifiers[node.name] = identifier
        used.insert(identifier)
    }

    return identifiers
}

static func appendUnique<T: Equatable>(_ values: [T], to destination: inout [T]) {
    for value in values where !destination.contains(value) {
        destination.append(value)
    }
}

private func orderedUnique(_ values: [String]) -> [String] {
    var seen = Set<String>()
    return values.filter { seen.insert($0).inserted }
}

private func uniqueLaneValues(_ values: [CGFloat]) -> [CGFloat] {
    values.reduce(into: [CGFloat]()) { lanes, value in
        guard !lanes.contains(where: { abs($0 - value) < 1 }) else { return }
        lanes.append(value)
    }
}

public func renderSequenceAsciiDiagram(
    _ diagram: AsciiSequenceDiagram,
    _ config: AsciiConfig,
    _ colorMode: ColorMode? = nil,
    _ theme: AsciiTheme? = nil
) -> String {
    if diagram.actors.isEmpty {
        return ""
    }

    let useAscii = config.useAscii

    let h: Character = useAscii ? "-" : "─"
    let v: Character = useAscii ? "|" : "│"
    let tl: Character = useAscii ? "+" : "┌"
    let tr: Character = useAscii ? "+" : "┐"
    let bl: Character = useAscii ? "+" : "└"
    let br: Character = useAscii ? "+" : "┘"
    let jt: Character = useAscii ? "+" : "┬"
    let jb: Character = useAscii ? "+" : "┴"
    let jl: Character = useAscii ? "+" : "├"
    let jr: Character = useAscii ? "+" : "┤"

    var actorIdx: [String: Int] = [:]
    for (i, a) in diagram.actors.enumerated() {
        actorIdx[a.id] = i
    }

    let boxPad = 1
    let actorBoxWidths = diagram.actors.map { asciiMaxLineWidth($0.label) + 2 * boxPad + 2 }
    let halfBox = actorBoxWidths.map { Int(ceil(Double($0) / 2.0)) }
    let actorBoxHeights = diagram.actors.map { asciiLineCount($0.label) + 2 }
    let actorBoxH = max(actorBoxHeights.max() ?? 3, 3)

    var adjMaxWidth = Array(repeating: 0, count: max(diagram.actors.count - 1, 0))
    for msg in diagram.messages {
        guard let fi = actorIdx[msg.from], let ti = actorIdx[msg.to] else { continue }
        if fi == ti { continue }
        let lo = min(fi, ti)
        let hi = max(fi, ti)
        let needed = asciiMaxLineWidth(msg.label) + 4
        let numGaps = hi - lo
        if numGaps <= 0 { continue }
        let perGap = Int(ceil(Double(needed) / Double(numGaps)))
        if lo < hi {
            for g in lo..<hi where g < adjMaxWidth.count {
                adjMaxWidth[g] = max(adjMaxWidth[g], perGap)
            }
        }
    }

    var llX = Array(repeating: 0, count: diagram.actors.count)
    if !diagram.actors.isEmpty {
        llX[0] = halfBox[0]
    }
    if diagram.actors.count > 1 {
        for i in 1..<diagram.actors.count {
            let gap = max(halfBox[i - 1] + halfBox[i] + 2, max(adjMaxWidth[i - 1] + 2, 10))
            llX[i] = llX[i - 1] + gap
        }
    }

    var msgArrowY: [Int] = Array(repeating: 0, count: diagram.messages.count)
    var msgLabelY: [Int] = Array(repeating: 0, count: diagram.messages.count)
    var blockStartY: [Int: Int] = [:]
    var blockEndY: [Int: Int] = [:]
    var divYMap: [String: Int] = [:]
    var notePositions: [AsciiSequenceNotePlacement] = []

    var curY = actorBoxH

    if !diagram.messages.isEmpty {
        for m in 0..<diagram.messages.count {
            for b in 0..<diagram.blocks.count where diagram.blocks[b].startIndex == m {
                curY += 2
                blockStartY[b] = curY - 1
            }

            for b in 0..<diagram.blocks.count {
                let block = diagram.blocks[b]
                for d in 0..<block.dividers.count where block.dividers[d].index == m {
                    curY += 1
                    divYMap["\(b):\(d)"] = curY
                    curY += 1
                }
            }

            curY += 1
            let msg = diagram.messages[m]
            let isSelfMsg = msg.from == msg.to
            let msgLines = asciiLineCount(msg.label)

            if isSelfMsg {
                msgLabelY[m] = curY + 1
                msgArrowY[m] = curY
                curY += 2 + msgLines
            } else {
                msgLabelY[m] = curY
                msgArrowY[m] = curY + msgLines
                curY += msgLines + 1
            }

            for note in diagram.notes where note.afterIndex == m {
                curY += 1
                let nLines = splitAsciiLines(note.text)
                let nWidth = (nLines.map { $0.count }.max() ?? 0) + 4
                let nHeight = nLines.count + 2

                let aIdx = actorIdx[note.actorIds.first ?? ""] ?? 0
                var nx: Int
                switch note.position {
                case "left":
                    nx = llX[aIdx] - nWidth - 1
                case "right":
                    nx = llX[aIdx] + 2
                default:
                    if note.actorIds.count >= 2 {
                        let aIdx2 = actorIdx[note.actorIds[1]] ?? aIdx
                        nx = Int(floor(Double(llX[aIdx] + llX[aIdx2]) / 2.0)) - Int(floor(Double(nWidth) / 2.0))
                    } else {
                        nx = llX[aIdx] - Int(floor(Double(nWidth) / 2.0))
                    }
                }
                nx = max(0, nx)

                notePositions.append(AsciiSequenceNotePlacement(x: nx, y: curY, width: nWidth, height: nHeight, lines: nLines))
                curY += nHeight
            }

            for b in 0..<diagram.blocks.count where diagram.blocks[b].endIndex == m {
                curY += 1
                blockEndY[b] = curY
                curY += 1
            }
        }
    }

    curY += 1
    let footerY = curY
    let totalH = footerY + actorBoxH

    let lastLL = llX.last ?? 0
    let lastHalf = halfBox.last ?? 0
    var totalW = lastLL + lastHalf + 2

    for msg in diagram.messages {
        if msg.from == msg.to {
            let fi = actorIdx[msg.from] ?? 0
            let selfRight = llX[fi] + 6 + 2 + msg.label.count
            totalW = max(totalW, selfRight + 1)
        }
    }
    for np in notePositions {
        totalW = max(totalW, np.x + np.width + 1)
    }

    var canvas = mkCanvas(totalW, max(0, totalH - 1))
    var rc = mkRoleCanvas(totalW, max(0, totalH - 1))

    func setC(_ x: Int, _ y: Int, _ ch: Character, _ role: CharRole) {
        if x >= 0, y >= 0 {
            if x >= canvas.count || y >= (canvas.first?.count ?? 0) {
                _ = increaseSize(&canvas, x, y)
                _ = increaseRoleCanvasSize(&rc, x, y)
            }
            if x < canvas.count, y < (canvas.first?.count ?? 0) {
                canvas[x][y] = ch
                setRole(&rc, x, y, role)
            }
        }
    }

    func drawActorBox(_ cx: Int, _ topY: Int, _ label: String) {
        let lines = splitAsciiLines(label)
        let maxW = asciiMaxLineWidth(label)
        let w = maxW + (2 * boxPad) + 2
        let hBox = lines.count + 2
        let left = cx - Int(floor(Double(w) / 2.0))

        setC(left, topY, tl, .border)
        if w > 2 {
            for x in 1..<(w - 1) {
                setC(left + x, topY, h, .border)
            }
        }
        setC(left + w - 1, topY, tr, .border)

        for (i, line) in lines.enumerated() {
            let row = topY + 1 + i
            setC(left, row, v, .border)
            setC(left + w - 1, row, v, .border)
            let ls = left + 1 + boxPad + Int(floor(Double(maxW - line.count) / 2.0))
            for (j, ch) in line.enumerated() {
                setC(ls + j, row, ch, .text)
            }
        }

        let bottomY = topY + hBox - 1
        setC(left, bottomY, bl, .border)
        if w > 2 {
            for x in 1..<(w - 1) {
                setC(left + x, bottomY, h, .border)
            }
        }
        setC(left + w - 1, bottomY, br, .border)
    }

    for i in 0..<diagram.actors.count {
        let x = llX[i]
        if actorBoxH <= footerY {
            for y in actorBoxH...footerY {
                setC(x, y, v, .line)
            }
        }
    }

    for i in 0..<diagram.actors.count {
        let actor = diagram.actors[i]
        drawActorBox(llX[i], 0, actor.label)
        drawActorBox(llX[i], footerY, actor.label)

        if !useAscii {
            setC(llX[i], actorBoxH - 1, jt, .junction)
            setC(llX[i], footerY, jb, .junction)
        }
    }

    for m in 0..<diagram.messages.count {
        let msg = diagram.messages[m]
        guard let fi = actorIdx[msg.from], let ti = actorIdx[msg.to] else { continue }
        let fromX = llX[fi]
        let toX = llX[ti]
        let isSelfMsg = fi == ti
        let isDashed = msg.lineStyle == "dashed"
        let isFilled = msg.arrowHead == "filled"

        let lineChar: Character = isDashed ? (useAscii ? "." : "╌") : h

        if isSelfMsg {
            let y0 = msgArrowY[m]
            let loopW = max(4, 4)

            setC(fromX, y0, jl, .junction)
            if fromX + 1 < fromX + loopW {
                for x in (fromX + 1)..<(fromX + loopW) {
                    setC(x, y0, lineChar, .line)
                }
            }
            setC(fromX + loopW, y0, useAscii ? "+" : "┐", .corner)

            setC(fromX + loopW, y0 + 1, v, .line)
            let labelX = fromX + loopW + 2
            let selfLabelLines = splitAsciiLines(msg.label)
            for (lineIdx, selfLine) in selfLabelLines.enumerated() {
                for (i, ch) in selfLine.enumerated() {
                    if labelX + i < totalW {
                        setC(labelX + i, y0 + 1 + lineIdx, ch, .text)
                    }
                }
            }

            let arrowChar: Character = isFilled ? (useAscii ? "<" : "◀") : (useAscii ? "<" : "◁")
            setC(fromX, y0 + 2, arrowChar, .arrow)
            if fromX + 1 < fromX + loopW {
                for x in (fromX + 1)..<(fromX + loopW) {
                    setC(x, y0 + 2, lineChar, .line)
                }
            }
            setC(fromX + loopW, y0 + 2, useAscii ? "+" : "┘", .corner)
        } else {
            let labelY = msgLabelY[m]
            let arrowY = msgArrowY[m]
            let leftToRight = fromX < toX

            let midX = Int(floor(Double(fromX + toX) / 2.0))
            let msgLines = splitAsciiLines(msg.label)
            for (lineIdx, line) in msgLines.enumerated() {
                let labelStart = midX - Int(floor(Double(line.count) / 2.0))
                let y = labelY + lineIdx
                for (i, ch) in line.enumerated() {
                    let lx = labelStart + i
                    if lx >= 0, lx < totalW {
                        setC(lx, y, ch, .text)
                    }
                }
            }

            if leftToRight {
                if fromX + 1 < toX {
                    for x in (fromX + 1)..<toX {
                        setC(x, arrowY, lineChar, .line)
                    }
                }
                let ah: Character = isFilled ? (useAscii ? ">" : "▶") : (useAscii ? ">" : "▷")
                setC(toX, arrowY, ah, .arrow)
            } else {
                if toX + 1 < fromX {
                    for x in (toX + 1)..<fromX {
                        setC(x, arrowY, lineChar, .line)
                    }
                }
                let ah: Character = isFilled ? (useAscii ? "<" : "◀") : (useAscii ? "<" : "◁")
                setC(toX, arrowY, ah, .arrow)
            }
        }
    }

    for b in 0..<diagram.blocks.count {
        let block = diagram.blocks[b]
        guard let topY = blockStartY[b], let botY = blockEndY[b] else { continue }

        var minLX = totalW
        var maxLX = 0
        if block.startIndex <= block.endIndex {
            for m in block.startIndex...block.endIndex {
                if m >= diagram.messages.count { break }
                let msg = diagram.messages[m]
                let f = actorIdx[msg.from] ?? 0
                let t = actorIdx[msg.to] ?? 0
                minLX = min(minLX, llX[min(f, t)])
                maxLX = max(maxLX, llX[max(f, t)])
            }
        }

        let bLeft = max(0, minLX - 4)
        let bRight = min(totalW - 1, maxLX + 4)

        setC(bLeft, topY, tl, .border)
        if bLeft + 1 < bRight {
            for x in (bLeft + 1)..<bRight {
                setC(x, topY, h, .border)
            }
        }
        setC(bRight, topY, tr, .border)

        let hdrLabel = block.label.map { "\(block.type) [\($0)]" } ?? block.type
        let hdrLines = splitAsciiLines(hdrLabel)
        for (lineIdx, line) in hdrLines.enumerated() where topY + lineIdx < botY {
            for (i, ch) in line.enumerated() where bLeft + 1 + i < bRight {
                setC(bLeft + 1 + i, topY + lineIdx, ch, .text)
            }
        }

        setC(bLeft, botY, bl, .border)
        if bLeft + 1 < bRight {
            for x in (bLeft + 1)..<bRight {
                setC(x, botY, h, .border)
            }
        }
        setC(bRight, botY, br, .border)

        if topY + 1 < botY {
            for y in (topY + 1)..<botY {
                setC(bLeft, y, v, .border)
                setC(bRight, y, v, .border)
            }
        }

        for d in 0..<block.dividers.count {
            guard let dY = divYMap["\(b):\(d)"] else { continue }
            let dashChar: Character = useAscii ? "-" : "╌"
            setC(bLeft, dY, jl, .junction)
            if bLeft + 1 < bRight {
                for x in (bLeft + 1)..<bRight {
                    setC(x, dY, dashChar, .line)
                }
            }
            setC(bRight, dY, jr, .junction)
            if let dLabel = block.dividers[d].label {
                let dStr = "[\(dLabel)]"
                for (i, ch) in dStr.enumerated() where bLeft + 1 + i < bRight {
                    setC(bLeft + 1 + i, dY, ch, .text)
                }
            }
        }
    }

    for np in notePositions {
        _ = increaseSize(&canvas, np.x + np.width, np.y + np.height)
        _ = increaseRoleCanvasSize(&rc, np.x + np.width, np.y + np.height)

        setC(np.x, np.y, tl, .border)
        if np.width > 2 {
            for x in 1..<(np.width - 1) {
                setC(np.x + x, np.y, h, .border)
            }
        }
        setC(np.x + np.width - 1, np.y, tr, .border)

        for (l, line) in np.lines.enumerated() {
            let ly = np.y + 1 + l
            setC(np.x, ly, v, .border)
            setC(np.x + np.width - 1, ly, v, .border)
            for (i, ch) in line.enumerated() {
                setC(np.x + 2 + i, ly, ch, .text)
            }
        }

        let by = np.y + np.height - 1
        setC(np.x, by, bl, .border)
        if np.width > 2 {
            for x in 1..<(np.width - 1) {
                setC(np.x + x, by, h, .border)
            }
        }
        setC(np.x + np.width - 1, by, br, .border)
    }

    _ = sequenceClassifyBoxChar("+")
    return canvasToString(
        canvas,
        options: CanvasToStringOptions(roleCanvas: rc, colorMode: colorMode, theme: theme)
    )
}

private func _parseStateDiagram(_ lines: [String]) throws -> ParsedGraph {
    var graph = _WorkingGraph(direction: .TD)

    var compositeStack: [ParsedSubgraph] = []
    var compositeStateIds = Set<String>()
    var startCount = 0
    var endCount = 0

    if lines.count <= 1 {
        return graph.toParsedGraph()
    }

    for line in lines.dropFirst() {
        if let dirMatch = _regexGroups(#"^direction\s+(TD|TB|LR|BT|RL)\s*$"#, line, caseInsensitive: true),
           let dirToken = dirMatch[safe: 1],
           let direction = _parseDirection(dirToken)
        {
            if !compositeStack.isEmpty {
                compositeStack[compositeStack.count - 1].direction = direction
            } else {
                graph.direction = direction
            }
            continue
        }

        // --- linkStyle in state diagrams ---
        if let lsMatch = _regexGroups(#"^linkStyle\s+(default|[\d,\s]+)\s+(.+)$"#, line),
           let target = lsMatch[safe: 1],
           let propsRaw = lsMatch[safe: 2]
        {
            let props = _parseStyleProps(propsRaw)
            if target.trimmingCharacters(in: .whitespacesAndNewlines) == "default" {
                var merged = graph.linkStyles[-1] ?? [:]
                for (k, v) in props { merged[k] = v }
                graph.linkStyles[-1] = merged
            } else {
                let indices = target.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
                for idx in indices {
                    var merged = graph.linkStyles[idx] ?? [:]
                    for (k, v) in props { merged[k] = v }
                    graph.linkStyles[idx] = merged
                }
            }
            continue
        }

        if let compositeMatch = _regexGroups(#"^state\s+(?:\"([^\"]+)\"\s+as\s+)?([\w\p{L}]+)\s*\{$"#, line),
           let id = compositeMatch[safe: 2]
        {
            let raw1 = compositeMatch[safe: 1]
            let label = (raw1?.isEmpty == false) ? raw1! : id
            compositeStack.append(ParsedSubgraph(id: id, label: label, nodeIds: [], children: [], direction: nil))
            compositeStateIds.insert(id)
            graph.nodesById.removeValue(forKey: id)
            graph.nodeOrder.removeAll { $0 == id }
            continue
        }

        if line == "}" {
            let completed = compositeStack.popLast()
            if let completed {
                if !compositeStack.isEmpty {
                    compositeStack[compositeStack.count - 1].children.append(completed)
                } else {
                    graph.subgraphs.append(completed)
                }
            }
            continue
        }

        if let aliasMatch = _regexGroups(#"^state\s+\"([^\"]+)\"\s+as\s+([\w\p{L}]+)\s*$"#, line),
           let labelRaw = aliasMatch[safe: 1],
           let id = aliasMatch[safe: 2]
        {
            let label = original_src_multiline_utils.normalizeBrTags(labelRaw)
            _registerStateNode(&graph, &compositeStack, ParsedNode(id: id, label: label, shape: .rounded))
            continue
        }

        if let transitionMatch = _regexGroups(#"^(\[\*\]|[\w\p{L}-]+)\s*(-->)\s*(\[\*\]|[\w\p{L}-]+)(?:\s*:\s*(.+))?$"#, line),
           let sourceRaw = transitionMatch[safe: 1],
           let targetRaw = transitionMatch[safe: 3]
        {
            var sourceId = sourceRaw
            var targetId = targetRaw
            let rawLabel = transitionMatch[safe: 4]?.trimmingCharacters(in: .whitespacesAndNewlines)
            let edgeLabel = (rawLabel?.isEmpty == false) ? original_src_multiline_utils.normalizeBrTags(rawLabel!) : nil

            if sourceId == "[*]" {
                startCount += 1
                sourceId = startCount > 1 ? "_start\(startCount)" : "_start"
                _registerStateNode(&graph, &compositeStack, ParsedNode(id: sourceId, label: "", shape: .stateStart))
            } else if !compositeStateIds.contains(sourceId) {
                _ensureStateNode(&graph, &compositeStack, sourceId)
            }

            if targetId == "[*]" {
                endCount += 1
                targetId = endCount > 1 ? "_end\(endCount)" : "_end"
                _registerStateNode(&graph, &compositeStack, ParsedNode(id: targetId, label: "", shape: .stateEnd))
            } else if !compositeStateIds.contains(targetId) {
                _ensureStateNode(&graph, &compositeStack, targetId)
            }

            graph.edges.append(
                ParsedEdge(
                    source: sourceId,
                    target: targetId,
                    label: edgeLabel,
                    style: .solid,
                    hasArrowStart: false,
                    hasArrowEnd: true
                )
            )
            continue
        }

        if let descMatch = _regexGroups(#"^([\w\p{L}-]+)\s*:\s*(.+)$"#, line),
           let id = descMatch[safe: 1],
           let labelRaw = descMatch[safe: 2]
        {
            let label = original_src_multiline_utils.normalizeBrTags(labelRaw.trimmingCharacters(in: .whitespacesAndNewlines))
            _registerStateNode(&graph, &compositeStack, ParsedNode(id: id, label: label, shape: .rounded))
            continue
        }
    }

    return graph.toParsedGraph()
}

private func shiftTowardsNodeOnSide(_ slHolder: SelfLoopHolder, _ side: PortSide,
                                      _ nextFreeRoutingSlotAtPort: inout [Int],
                                      _ labelCrossingMatrix: [[Bool]]) {
    let slLoops = slHolder.getSLHyperLoops()
        .filter { $0.getOccupiedPortSides().contains(side) }
        .sorted { $0.getRoutingSlot(side) < $1.getRoutingSlot(side) }

    var minLPortIndex = Int.max
    var maxLPortIndex = Int.min
    for lPort in slHolder.getLNode().getPorts() {
        if lPort.getSide() == side {
            minLPortIndex = min(minLPortIndex, lPort.id)
            maxLPortIndex = max(maxLPortIndex, lPort.id)
        }
    }

    if minLPortIndex == Int.max {
        for (i, loop) in slLoops.enumerated() {
            loop.setRoutingSlot(side, i)
        }
    } else {
        var slotAssignedToLabel = [Int](repeating: -1, count: labelCrossingMatrix.count)

        for slLoop in slLoops {
            guard let activeAtPort = slLoopActivityOverPorts[ObjectIdentifier(slLoop)] else { continue }
            var lowestAvailableSlot = 0

            for portIndex in minLPortIndex...maxLPortIndex {
                if activeAtPort[portIndex] {
                    lowestAvailableSlot = max(lowestAvailableSlot, nextFreeRoutingSlotAtPort[portIndex])
                }
            }

            if let ourLabels = slLoop.getSLLabels() {
                let ourLabelIdx = ourLabels.id
                var slotsWithLabelConflicts = Set<Int>()

                for otherLabelIdx in 0..<labelCrossingMatrix.count {
                    if labelCrossingMatrix[ourLabelIdx][otherLabelIdx] {
                        slotsWithLabelConflicts.insert(slotAssignedToLabel[otherLabelIdx])
                    }
                }

                while slotsWithLabelConflicts.contains(lowestAvailableSlot) {
                    lowestAvailableSlot += 1
                }
            }

            slLoop.setRoutingSlot(side, lowestAvailableSlot)
            for portIndex in minLPortIndex...maxLPortIndex {
                if activeAtPort[portIndex] {
                    nextFreeRoutingSlotAtPort[portIndex] = lowestAvailableSlot + 1
                }
            }

            if let endLabels = slLoop.getSLLabels() {
                slotAssignedToLabel[endLabels.id] = lowestAvailableSlot
            }
        }
    }
}

package func insideBlockShift(_ bal: org_eclipse_elk_alg_layered_p4nodes_bk_BKAlignedLayout) {
    let blocks = org_eclipse_elk_alg_layered_p4nodes_bk_BKNodePlacer.getBlocks(bal)
    var seenRoots: Set<ObjectIdentifier> = []

    for layer in layeredGraph.getLayers() {
        for candidate in layer.getNodes() {
            guard let root = bal.root[candidate.id] else {
                continue
            }
            let rootKey = ObjectIdentifier(root)
            if seenRoots.contains(rootKey) || blocks[root] == nil {
                continue
            }
            seenRoots.insert(rootKey)

            var spaceAbove = root.getMargin().top
            var spaceBelow = root.getSize().y + root.getMargin().bottom
            bal.innerShift[root.id] = 0.0

            var current = root
            while let next = bal.align[current.id], next !== root {
                guard let edge = org_eclipse_elk_alg_layered_p4nodes_bk_BKNodePlacer.getEdge(current, next),
                      let source = edge.getSource(),
                      let target = edge.getTarget()
                else {
                    current = next
                    continue
                }

                let portPosDiff: Double
                if bal.hdir == .LEFT {
                    portPosDiff = target.getPosition().y + target.getAnchor().y
                        - source.getPosition().y - source.getAnchor().y
                } else {
                    portPosDiff = source.getPosition().y + source.getAnchor().y
                        - target.getPosition().y - target.getAnchor().y
                }

                let nextInnerShift = bal.innerShift[current.id] + portPosDiff
                bal.innerShift[next.id] = nextInnerShift

                spaceAbove = Swift.max(spaceAbove, next.getMargin().top - nextInnerShift)
                spaceBelow = Swift.max(
                    spaceBelow,
                    nextInnerShift + next.getSize().y + next.getMargin().bottom
                )

                current = next
            }

            current = root
            repeat {
                bal.innerShift[current.id] += spaceAbove
                guard let next = bal.align[current.id] else {
                    break
                }
                current = next
            } while current !== root

            bal.blockSize[root.id] = spaceAbove + spaceBelow
        }
    }
}

static func unique(_ names: [String]) -> [String] {
    var seen: [String: Int] = [:]
    return names.map { n in
        let k = n.lowercased()
        seen[k, default: 0] += 1
        return seen[k]! == 1 ? n : "\(n)\(seen[k]!)"
    }
}

