func run(using context: CommandContext, signature: Signature) async throws {
    prepareDependencies {
        $0.logger = Logger(component: "build-backlog-stats")
    }
    @Dependency(\.logger) var logger

    logger.info("Running build-backlog-stats...")

    let packageIds = try await fetchBuildCandidates(
        context.application.db,
        withLatestSwiftVersion: !signature.withoutLatestSwiftVersion
    )

    if let limit = signature.limit {
        logger.info("Checking \(limit) of \(packageIds.count) candidates...")
    } else {
        logger.info("Checking all \(packageIds.count) candidates")
    }

    var totalBuildCount = 0
    var platformCounts = [Build.Platform: Int]()
    var swiftVersionCounts = [SwiftVersion: Int]()

    for (idx, pkgId) in packageIds.prefix(signature.limit ?? packageIds.count).enumerated() {
        if idx > 0, idx % 50 == 0 {
            logger.info("Checking candidate #\(idx)")
        }
        let triggerInfo = try await findMissingBuilds(
            context.application.db,
            packageId: pkgId
        )
        for trigger in triggerInfo {
            for pair in trigger.buildPairs {
                totalBuildCount += 1
                platformCounts[pair.platform, default: 0] += 1
                swiftVersionCounts[pair.swiftVersion, default: 0] += 1
            }
        }
    }

    logger.info("Total build count: \(totalBuildCount)")

    for platform in Build.Platform.allActive {
        if let count = platformCounts[platform] {
            logger.info("\(platform): \(count)")
        }
    }

    for swiftVersion in SwiftVersion.allActive {
        if let count = swiftVersionCounts[swiftVersion] {
            logger.info("\(swiftVersion): \(count)")
        }
    }
}

func uniqName(item: SyntaxStructure, relationship: String) -> String {
    guard let name = item.fullName else { return "" }
    var newName = name
    let linkTypeKey = name + "LinkType"
    if uniqElementNames.contains(name) {
        newName += "\(index)"
        index += 1
        if item.kind == ElementKind.extension,
           uniqueNameForElement.keys.first(where: { $0.name == name && $0.kind != .extension }) != nil
        {
            var connect = "\(name) \(linkTypeDependency) \(newName)"
            if let relStyle = configuration.relationships.dependency?.style?.plantuml {
                connect += " \(relStyle)"
            }
            connect += " : \(configuration.relationships.dependency?.label ?? relationship)"
            extnConnections.append(connect) // "aPublicStruct <.. aPublicStruct0 : ext"
        }
    } else {
        uniqElementNames.append(name)
        uniqElementAndTypes[name] = relationship

        if relationship == "inherits" {
            uniqElementAndTypes[linkTypeKey] = linkTypeInheritance
        } else if relationship == "conforms to" {
            uniqElementAndTypes[linkTypeKey] = linkTypeRealize
        } else if relationship == "ext" {
            uniqElementAndTypes[linkTypeKey] = linkTypeDependency
        } else {
            uniqElementAndTypes[linkTypeKey] = linkTypeGeneric
        }
    }
    uniqueNameForElement[item] = newName
    return newName
}

func uniqued() -> [Element] {
