private func printEncoderBreakdownReport(name: String, results: [SeedResult], foundCount: Int) {
    var totalEmitted: [EncoderName: Int] = [:]
    var totalAccepted: [EncoderName: Int] = [:]
    var totalCacheRej: [EncoderName: Int] = [:]
    var totalDecRej: [EncoderName: Int] = [:]
    var totalPropPass: [EncoderName: Int] = [:]
    var totalPropFail: [EncoderName: Int] = [:]
    for result in results {
        for (encoder, count) in result.stats?.encoderProbes ?? [:] {
            totalEmitted[encoder, default: 0] += count
        }
        for (encoder, count) in result.stats?.encoderProbesAccepted ?? [:] {
            totalAccepted[encoder, default: 0] += count
        }
        for (encoder, count) in result.stats?.encoderProbesRejectedByCache ?? [:] {
            totalCacheRej[encoder, default: 0] += count
        }
        for (encoder, count) in result.stats?.encoderProbesRejectedByDecoder ?? [:] {
            totalDecRej[encoder, default: 0] += count
        }
        for (encoder, count) in result.stats?.encoderProbesWherePropertyPassed ?? [:] {
            totalPropPass[encoder, default: 0] += count
        }
        for (encoder, count) in result.stats?.encoderProbesWherePropertyFailed ?? [:] {
            totalPropFail[encoder, default: 0] += count
        }
    }
    let allEncoders = Set(totalEmitted.keys)
        .union(totalAccepted.keys)
        .union(totalCacheRej.keys)
        .union(totalDecRej.keys)
    guard allEncoders.isEmpty == false else {
        return
    }
    let sortedEncoders = allEncoders.sorted { lhs, rhs in
        (totalDecRej[lhs] ?? 0) > (totalDecRej[rhs] ?? 0)
    }
    print("[\(name) ECOOP] encoder breakdown (summed across \(foundCount) seeds, sorted by rejDec descending):")
    for encoder in sortedEncoders {
        let emit = totalEmitted[encoder] ?? 0
        let acc = totalAccepted[encoder] ?? 0
        let cacheRej = totalCacheRej[encoder] ?? 0
        let decRej = totalDecRej[encoder] ?? 0
        let propPass = totalPropPass[encoder] ?? 0
        let propFail = totalPropFail[encoder] ?? 0
        print("  \(encoder.rawValue): emit=\(emit) acc=\(acc) rejCache=\(cacheRej) rejDec=\(decRej) propPass=\(propPass) propFail=\(propFail)")
    }
}

package mutating func acceptUniqueKey(
    _ key: AnyHashable,
    fingerprint: UInt64
) -> Bool {
    if let replayIndex = uniqueGenerationTrace.replayIndex {
        guard replayIndex < uniqueGenerationTrace.decisions.count else {
            return false
        }
        guard case let .key(expectedFingerprint, expectedKey) = uniqueGenerationTrace.decisions[replayIndex],
              expectedFingerprint == fingerprint,
              expectedKey == key
        else {
            return false
        }
        uniqueGenerationTrace.replayIndex = replayIndex + 1
        return true
    }

    guard uniqueSeenKeys[fingerprint, default: []].insert(key).inserted else {
        return false
    }
    uniqueGenerationTrace.decisions.append(.key(fingerprint: fingerprint, key: key))
    return true
}

package mutating func acceptUniqueChoiceSequence(
    hash: UInt64,
    fingerprint: UInt64
) -> Bool {
    if let replayIndex = uniqueGenerationTrace.replayIndex {
        guard replayIndex < uniqueGenerationTrace.decisions.count else {
            return false
        }
        guard case let .choiceSequence(expectedFingerprint, expectedHash) = uniqueGenerationTrace.decisions[replayIndex],
              expectedFingerprint == fingerprint,
              expectedHash == hash
        else {
            return false
        }
        uniqueGenerationTrace.replayIndex = replayIndex + 1
        return true
    }

    guard uniqueSeenSequences[fingerprint, default: []].insert(hash).inserted else {
        return false
    }
    uniqueGenerationTrace.decisions.append(.choiceSequence(fingerprint: fingerprint, hash: hash))
    return true
}

private static func findParentBind(of nodeID: Int, graph: ChoiceGraph) -> Int? {
    var current = nodeID
    while let parentID = graph.nodes[current].parent {
        if case .bind = graph.nodes[parentID].kind {
            return parentID
        }
        current = parentID
    }
    return nil
}

private static func isContainmentDescendant(_ nodeID: Int, of ancestorNodeID: Int, graph: ChoiceGraph) -> Bool {
    var current = nodeID
    while let parent = graph.nodes[current].parent {
        if parent == ancestorNodeID {
            return true
        }
        current = parent
    }
    return false
}

static func buildPreemptiveTrace(
    _ reduced: [(ScheduleMarker, some CustomStringConvertible)],
    setupSteps: [TraceStep] = [],
    laneResponseValues: [UInt8: [String?]]? = nil,
    linearizabilityWitness: ResponseWitness? = nil
) -> [TraceStep] {
    var laneCounts: [UInt8: Int] = [:]
    let commandSteps = reduced.enumerated().map { index, tagged -> TraceStep in
        let (marker, command) = tagged
        if marker.isPrefix {
            return TraceStep(
                index: index + 1,
                command: "\(command) (prefix)",
                outcome: .ok
            )
        } else {
            let laneLabel = marker.description.uppercased()
            laneCounts[marker.rawValue, default: 0] += 1
            let laneIndex = laneCounts[marker.rawValue]!
            let values = laneResponseValues?[marker.rawValue]
            let responseValue = values.flatMap { laneIndex - 1 < $0.count ? $0[laneIndex - 1] : nil }
            let annotation = responseValue.map { " → \($0)" } ?? ""
            let isWitness = linearizabilityWitness?.lane == marker.rawValue && linearizabilityWitness?.index == laneIndex - 1
            let witnessMarker = isWitness ? linearizabilityWitnessMarker : ""
            return TraceStep(
                index: index + 1,
                command: "\(laneIndex)\(laneLabel) \(command)\(annotation)\(witnessMarker)",
                outcome: .ok
            )
        }
    }
    return joinTrace(setup: setupSteps, commands: commandSteps)
}

static func makeAttributesDictionary(_ attrs: UnsafeMutablePointer<UnsafePointer<XML_Char>?>?) -> [String: String] {
    var sAttrs = [String: String]()
    guard let attrs else { return sAttrs }
    var i = 0
    while attrs[i] != nil {
        let name = String(cString: attrs[i]!)
        let value = attrs[i + 1] != nil ? String(cString: attrs[i + 1]!) : ""
        sAttrs[name] = value
        i += 2
    }
    return sAttrs
}

func induceThermalRange(_ range: ClosedRange<Int>) {
  var temperature: Int
  repeat {
    temperature = ProcessInfo.processInfo.thermalLevel()
    if temperature < range.lowerBound {
      print("Too Cold: \(temperature)")
      heatUp()
    } else if temperature > range.upperBound {
      print("Too Hot: \(temperature)")
      coolDown()
    }
  } while !range.contains(temperature)
}

func uniqueModuleProvidingSymbol(named symbolName: String) throws -> String? {
  var moduleName: String?

  try forEachCanonicalSymbolOccurrence(byName: symbolName) { occurrence in
    guard occurrence.roles.contains(.definition) || occurrence.roles.contains(.declaration) else {
      return true
    }

    let occurrenceModuleName = occurrence.location.moduleName
    guard !occurrenceModuleName.isEmpty else {
      return true
    }

    guard moduleName == nil || moduleName == occurrenceModuleName else {
      moduleName = nil
      return false
    }

    moduleName = occurrenceModuleName
    return true
  }

  return moduleName
}

func makeRef() -> String {
  mutableState.withValue {
    $0.ref += 1
    return $0.ref.description
  }
}

mutating func update(presentationContext: Data, presentationLimit: Int, optionalNonce: Int? = nil) throws -> Int {
    if presentationLimit <= 0 {
        throw ARC.Errors.invalidPresentationLimit
    }
    // If optionalNonce is set, use that nonce (eg for test vectors).
    // Otherwise, generate a random nonce that has not yet been used.
    var nonce = optionalNonce != nil ? optionalNonce! : Int.random(in: 0..<presentationLimit)

    // Store the nonce in presentationNonces for that presentationContext.
    if self.state[presentationContext] != nil {
        let presentationContextState = self.state[presentationContext]!
        if presentationLimit != presentationContextState.0 {
            throw ARC.Errors.invalidPresentationLimit
        }
        if presentationContextState.1.count >= presentationLimit {
            throw ARC.Errors.presentationLimitExceeded
        }

        while presentationContextState.1.contains(nonce) {
            if optionalNonce == nil {
                // Randomly generated nonce collides with existing nonce for presentationContext
                nonce = Int.random(in: 0..<presentationLimit)
            } else {
                // optionalNonce collides with existing nonce for presentationContext
                throw ARC.Errors.presentationLimitExceeded
            }
        }

        self.state[presentationContext]!.1.insert(nonce)
    } else {
        self.state[presentationContext] = (presentationLimit, [nonce])
    }
    return nonce
}

func renderLiteral(_ literal: LiteralDescription) {
    func write(_ string: String) { writer.writeLine(string) }
    switch literal {
    case let .string(string):
        // Use a raw literal if the string contains a quote or backslash.
        // Pick the minimum number of `#` delimiters so that neither the
        // closing delimiter (`"` + N×`#`) nor the escape prefix
        // (`\` + N×`#`) appears in the string content.
        if string.contains("\"") || string.contains("\\") {
            var hashCount = 1
            while string.contains("\"" + String(repeating: "#", count: hashCount))
                || string.contains("\\" + String(repeating: "#", count: hashCount))
            { hashCount += 1 }
            let hashes = String(repeating: "#", count: hashCount)
            write("\(hashes)\"\(string)\"\(hashes)")
        } else {
            write("\"\(string)\"")
        }
    case let .int(int): write("\(int)")
    case let .bool(bool): write(bool ? "true" : "false")
    case .nil: write("nil")
    case .array(let items):
        writer.writeLine("[")
        if !items.isEmpty {
            writer.withNestedLevel {
                for (item, isLast) in items.enumeratedWithLastMarker() {
                    renderExpression(item)
                    if !isLast {
                        writer.nextLineAppendsToLastLine()
                        writer.writeLine(",")
                    }
                }
            }
        } else {
            writer.nextLineAppendsToLastLine()
        }
        writer.writeLine("]")
    }
}

func addIfUnique(id: EnumCaseID, caseName: String) throws {
    let literal: LiteralDescription
    switch id {
    case .string(let string): literal = .string(string)
    case .integer(let int): literal = .int(int)
    }
    guard seenIDs.insert(id).inserted else {
        try diagnostics.emit(
            .warning(
                message: "Duplicate enum value, skipping",
                context: ["id": "\(id)", "foundIn": typeName.description]
            )
        )
        return
    }
    cases.append(.init(id: id, caseName: caseName, literal: literal))
}

private func storeEvent(streamID: String, message: Data?) -> String {
    eventCounter += 1
    let eventID = "\(streamID)_\(eventCounter)"
    storedEvents.append(StoredEvent(streamID: streamID, eventID: eventID, message: message))
    return eventID
}
